window.HERBULANCE_GLOSSARY=[{"term":"1RM (one-repetition maximum)","definition":"The maximum load a person can lift once with good technique. Often estimated rather than tested directly for safety.","volumes":[14]},{"term":"ABCDE Criteria","definition":"A clinical screening acronym for melanoma: Asymmetry, Border irregularity, Color variation, Diameter >6mm, and Evolving change.","volumes":[16]},{"term":"Abduction","definition":"Movement of an eye away from the nose.","volumes":[26]},{"term":"Aberration","definition":"An optical imperfection that can reduce image quality.","volumes":[26]},{"term":"Acanthosis Nigricans","definition":"A skin condition marked by velvety, hyperpigmented, papillomatous plaques in flexural folds (neck, armpits, groin).","volumes":[16]},{"term":"Accommodation","definition":"An adjustment to an environment or process that removes barriers and enables participation.","volumes":[25]},{"term":"Accommodation amplitude","definition":"The range of focusing adjustment available to an eye.","volumes":[26]},{"term":"Accommodation insufficiency","definition":"Difficulty sustaining the focusing adjustment required for near work.","volumes":[26]},{"term":"Acetylcholine","definition":"A neurotransmitter important in autonomic, neuromuscular and some brain functions.","volumes":[25]},{"term":"Acid Mantle","definition":"The slightly acidic film on the surface of human skin (typically pH 4.5 to 5.5) formed by sebum, sweat, and microbial breakdown products.","volumes":[16]},{"term":"Acid-base balance","definition":"The body's regulation of blood pH within a narrow, healthy range, strongly influenced by carbon dioxide and bicarbonate.","volumes":[21]},{"term":"Acne Vulgaris","definition":"A multifactorial disorder of the pilosebaceous unit involving hyperkeratinization, excess sebum, Cutibacterium acnes, and inflammation.","volumes":[16]},{"term":"Acoustic neuroma","definition":"A non-cancerous tumour of the nerve that carries hearing and balance signals. In modern terminology it is usually called a vestibular schwannoma.","volumes":[28]},{"term":"Acquired colour vision difference","definition":"A change in colour discrimination that develops after birth.","volumes":[26]},{"term":"Acrylates","definition":"Monomers and oligomers used in gel nails and artificial nail systems that polymerize under UV/LED light.","volumes":[16]},{"term":"Action potential","definition":"A rapid, self-regenerating electrical signal along a neuron's membrane.","volumes":[25]},{"term":"Active recovery","definition":"Very light activity (easy walking, gentle swimming) on recovery days to promote blood flow without adding load.","volumes":[14]},{"term":"Acute","definition":"Of short duration and often rapid onset, as in an acute infection or breath.","volumes":[21]},{"term":"Acute bronchitis","definition":"Short-term inflammation of the bronchi, usually caused by a virus.","volumes":[21]},{"term":"Acute mountain sickness","definition":"Symptoms from ascending too quickly to high altitude, including headache and nausea.","volumes":[21]},{"term":"Acute otitis media","definition":"Inflammation or infection of the middle ear, often with pain, fever or fluid behind the eardrum. Most common in young children.","volumes":[28]},{"term":"Acute stress","definition":"A short-lived stress response to a specific demand, usually followed by recovery.","volumes":[13]},{"term":"Adaptation","definition":"A change in the body or behaviour that helps a person meet demands over time.","volumes":[13]},{"term":"Adaptation","definition":"The body's structural and functional change in response to repeated, recoverable training stimuli.","volumes":[14]},{"term":"Adaptive lighting","definition":"Lighting adjusted to the needs of a person or task.","volumes":[26]},{"term":"Adaptogen","definition":"A marketing term for plant-based substances claimed to help the body resist stress. Evidence is limited and the term is not a regulated medical category.","volumes":[13]},{"term":"Adduction","definition":"Movement of an eye towards the nose.","volumes":[26]},{"term":"Adenosine","definition":"A molecule that builds up during wakefulness and contributes to sleep pressure.","volumes":[13]},{"term":"Adenosine triphosphate (ATP)","definition":"The molecule cells use to store and transfer energy, made with oxygen in mitochondria.","volumes":[21]},{"term":"ADHD","definition":"Attention-deficit hyperactivity disorder, a neurodevelopmental profile affecting attention, impulse regulation and activity.","volumes":[25]},{"term":"Adrenal glands","definition":"Glands above the kidneys. The medulla releases adrenaline; the cortex releases cortisol.","volumes":[13]},{"term":"Adrenaline","definition":"Also called epinephrine. A hormone and neurotransmitter that rapidly mobilises energy and raises alertness.","volumes":[13]},{"term":"Adulteration","definition":"Deliberate addition of foreign material (for example starch, dyes or other plant matter) to a product to increase profit or disguise low quality.","volumes":[3]},{"term":"Adverse childhood experiences","definition":"Potentially traumatic events during childhood, studied in relation to later health. Research is observational.","volumes":[13]},{"term":"Adverse effect","definition":"An unwanted or harmful effect of a treatment or exposure.","volumes":[25]},{"term":"Adverse food reaction","definition":"Any unwanted, reproducible response to a food. It is an umbrella term covering allergy, intolerance and other mechanisms.","volumes":[9]},{"term":"Aerobic base","definition":"The foundation of low-to-moderate intensity endurance training that supports all other training.","volumes":[14]},{"term":"Aerobic capacity (VO2max)","definition":"The maximum rate at which the body can take up and use oxygen during exercise; a key measure of cardiorespiratory fitness. Improves with regular aerobic training.","volumes":[14]},{"term":"Aerobic exercise","definition":"Sustained, rhythmic activity using large muscle groups that relies mainly on oxygen-dependent energy production, e.g. brisk walking, cycling, swimming.","volumes":[14]},{"term":"Aerosol","definition":"Fine respiratory particles that can remain suspended in air and travel farther than droplets.","volumes":[21]},{"term":"Afferent pathway","definition":"A nerve pathway carrying information towards the central nervous system.","volumes":[26]},{"term":"Age-related macular degeneration","definition":"A condition affecting the macula, more common with increasing age.","volumes":[26]},{"term":"Agonist","definition":"The primary muscle producing a movement — e.g. the quadriceps in knee extension.","volumes":[14]},{"term":"Ahimsa","definition":"The principle of non-violence central to Jain practice, underlying strictly vegetarian diets.","volumes":[9]},{"term":"Air trapping","definition":"Inability to fully exhale air, causing it to accumulate in the lungs, as in emphysema.","volumes":[21]},{"term":"Airway","definition":"Any passage that carries air to the lungs, from the nose to the smallest bronchioles.","volumes":[21]},{"term":"Airway clearance","definition":"Techniques or devices that help move mucus out of the lungs.","volumes":[21]},{"term":"Airway hyperresponsiveness","definition":"Airways that over-react and narrow excessively to triggers, central to asthma.","volumes":[21]},{"term":"Airway resistance","definition":"Opposition to airflow within the airways, strongly affected by airway diameter.","volumes":[21]},{"term":"ALA","definition":"Alpha-linolenic acid, an essential plant-derived omega-3 fatty acid.","volumes":[25]},{"term":"Alcohol","definition":"A depressant that can disrupt sleep and mood. Dependence needs professional help.","volumes":[13]},{"term":"Allantoin","definition":"A soothing compound that promotes epithelialization, softens keratin, and alleviates minor skin irritations.","volumes":[16]},{"term":"Allergen","definition":"A substance, usually a protein, that triggers an allergic immune response in a sensitised person.","volumes":[9]},{"term":"Allergen matrix","definition":"A table used by food businesses showing which allergens are in each dish or product.","volumes":[9]},{"term":"Allergic conjunctivitis","definition":"Inflammation of the conjunctiva triggered by an allergic response.","volumes":[26]},{"term":"Allergic Contact Dermatitis (ACD)","definition":"A delayed Type IV hypersensitivity reaction triggered when the immune system mounts a specific T-cell response to a chemical allergen.","volumes":[16]},{"term":"Allodynia","definition":"Pain caused by a stimulus that normally does not provoke pain.","volumes":[25]},{"term":"Allostasis","definition":"Achieving stability through change. The body adjusts many systems to meet demands.","volumes":[13]},{"term":"Allostatic load","definition":"A research concept describing cumulative wear from repeated or prolonged stress adaptation.","volumes":[13]},{"term":"Allostatic load","definition":"The cumulative biological cost of repeated or prolonged adaptation to stress.","volumes":[25]},{"term":"Allostatic state","definition":"A condition in which allostatic systems are adjusted to sustained demand.","volumes":[13]},{"term":"Alopecia Areata","definition":"An autoimmune condition where T-lymphocytes attack the hair follicle bulb, leading to smooth, well-demarcated circular patches of hair loss.","volumes":[16]},{"term":"Alpha Hydroxy Acid (AHA)","definition":"Water-soluble organic carboxylic acids (such as glycolic and lactic acid) that dissolve ionic bonds between corneocytes on the outer epidermis.","volumes":[16]},{"term":"Alpha-gal syndrome","definition":"An allergy to a sugar found in mammalian meat, linked to tick bites in some regions. Reactions may be delayed.","volumes":[9]},{"term":"Alveolar-capillary membrane","definition":"The thin barrier across which oxygen and carbon dioxide diffuse between air and blood.","volumes":[21]},{"term":"Alveoli","definition":"Tiny air sacs in the lungs where gas exchange with the blood occurs.","volumes":[21]},{"term":"Alzheimer disease","definition":"The most common cause of dementia, involving progressive neurodegeneration and characteristic pathology.","volumes":[25]},{"term":"Ambulatory","definition":"Able to walk; not confined to bed.","volumes":[21]},{"term":"Amino acid","definition":"A building block of proteins, including those in lung tissue.","volumes":[21]},{"term":"Amplitude","definition":"The size of a sound wave’s pressure change. It contributes to perceived loudness and is described using decibels.","volumes":[28]},{"term":"Amygdala","definition":"A group of brain structures involved in detecting salient or threatening information and linking events to emotional meaning.","volumes":[13]},{"term":"Amygdala","definition":"A temporal-lobe structure involved in emotional learning, threat detection and social processing.","volumes":[25]},{"term":"Amyloid","definition":"A protein fragment that can aggregate and form plaques in Alzheimer disease.","volumes":[25]},{"term":"Amyotrophic lateral sclerosis","definition":"A progressive motor neuron disease affecting upper and lower motor neurons.","volumes":[25]},{"term":"Anabolic window","definition":"The overstated idea that protein must be consumed within ~30 minutes post-workout; total daily intake matters most.","volumes":[14]},{"term":"Anaerobic","definition":"Occurring without oxygen; cells can make a little energy this way.","volumes":[21]},{"term":"Anaerobic metabolism","definition":"Energy production that does not require oxygen at that moment — the phosphagen and glycolytic systems. Used during short, hard efforts.","volumes":[14]},{"term":"Anagen Phase","definition":"The active proliferative growth phase of the hair follicle cycle, lasting 2 to 7 years on the human scalp.","volumes":[16]},{"term":"Anaphylaxis","definition":"A severe, potentially life-threatening allergic reaction that usually involves more than one body system. It is a medical emergency.","volumes":[9]},{"term":"Anaphylaxis","definition":"A severe, potentially life-threatening allergic reaction requiring immediate care.","volumes":[21]},{"term":"Anatomy","definition":"The study of the structure of the body.","volumes":[21]},{"term":"Androgenetic Alopecia (AGA)","definition":"Pattern hair loss influenced by genetic predisposition and dihydrotestosterone (DHT) sensitivity, causing progressive follicular miniaturization.","volumes":[16]},{"term":"Anemia","definition":"Low haemoglobin or red cells, reducing oxygen-carrying capacity.","volumes":[21]},{"term":"Antagonist","definition":"The muscle that opposes the agonist in a movement, controlling and slowing it — e.g. the hamstrings oppose the quadriceps when extending the knee.","volumes":[14]},{"term":"Anterior chamber","definition":"The fluid-filled space between the cornea and iris.","volumes":[26]},{"term":"Anterior segment","definition":"The front part of the eye, including the cornea, iris and lens.","volumes":[26]},{"term":"Anterior uveitis","definition":"Inflammation primarily affecting the front part of the uvea.","volumes":[26]},{"term":"Anti-VEGF","definition":"Medicines that inhibit vascular endothelial growth factor and are used for some retinal diseases.","volumes":[26]},{"term":"Anticipatory thinking","definition":"Mental rehearsal of possible future events, which can be helpful planning or unhelpful worry.","volumes":[13]},{"term":"Antihistamine","definition":"A medicine that blocks histamine effects. It can relieve some mild allergy symptoms but does not replace epinephrine in anaphylaxis.","volumes":[9]},{"term":"Antimicrobial","definition":"Able to destroy or inhibit microbes; some are in airway secretions.","volumes":[21]},{"term":"Antioxidant","definition":"A substance that helps neutralise oxidative stress; best obtained from a varied diet.","volumes":[21]},{"term":"Antiperspirant","definition":"A product containing aluminum salts that dissolve in sweat to form temporary physical gel plugs in eccrine sweat gland ducts.","volumes":[16]},{"term":"Antiviral","definition":"A medicine that targets a virus; for flu it works best started early and prescribed.","volumes":[21]},{"term":"Anxiety","definition":"An emotional and physical response to threat or uncertainty. Anxiety disorders are clinical conditions and differ from everyday worry.","volumes":[13]},{"term":"Anxiety disorder","definition":"A clinical condition defined by persistent, excessive anxiety causing impairment. Requires professional assessment.","volumes":[13]},{"term":"Aphasia","definition":"Impaired language production or comprehension due to acquired brain injury.","volumes":[25]},{"term":"Apnoea","definition":"A temporary pause in breathing.","volumes":[21]},{"term":"Apocrine Gland","definition":"Sweat glands concentrated in the armpits, groin, and perianal region that secrete a milky, lipid-rich fluid triggered by emotional stress.","volumes":[16]},{"term":"Appetite","definition":"Desire for food, influenced by hormones, habits, emotion and environment.","volumes":[13]},{"term":"Appraisal","definition":"The process of evaluating whether a situation is threatening, challenging or manageable and what resources are available.","volumes":[13]},{"term":"Apraxia","definition":"Difficulty carrying out learned movements despite adequate strength and sensation.","volumes":[25]},{"term":"Aqueous humour","definition":"Clear fluid produced by the ciliary body that circulates through the front of the eye.","volumes":[26]},{"term":"AREDS2","definition":"A specific supplement formulation studied for certain stages of age-related macular degeneration.","volumes":[26]},{"term":"ARFID","definition":"Avoidant/restrictive food intake disorder: a feeding and eating condition that can involve restricted intake not driven by body image. Needs professional assessment.","volumes":[9]},{"term":"Aril","definition":"A fleshy or lacy covering that grows around a seed. Mace is the aril of the nutmeg seed.","volumes":[3]},{"term":"Arterial blood gas (ABG)","definition":"A test measuring blood oxygen, carbon dioxide and pH.","volumes":[21]},{"term":"Artificial tears","definition":"Lubricating eye drops formulated to help relieve some ocular surface symptoms.","volumes":[26]},{"term":"Asbestos","definition":"Fibres that, when inhaled, can cause lung disease and cancer.","volumes":[21]},{"term":"Asbestosis","definition":"Lung scarring from inhaled asbestos fibres.","volumes":[21]},{"term":"Aspheric lens","definition":"A lens whose curvature changes across its surface rather than following a simple sphere.","volumes":[26]},{"term":"Aspiration","definition":"Entry of food, liquid or saliva into the airway.","volumes":[21]},{"term":"Assertiveness","definition":"Stating needs, opinions and boundaries clearly and respectfully, without aggression or passivity.","volumes":[13]},{"term":"Assessment","definition":"A professional evaluation conducted by a qualified clinician.","volumes":[13]},{"term":"Assistive technology","definition":"Products or systems that support function, communication, mobility or independence.","volumes":[25]},{"term":"Asthenopia","definition":"A clinical term for eye strain or visual fatigue.","volumes":[26]},{"term":"Asthma","definition":"A long-term condition of inflamed, twitchy airways causing variable airflow limitation.","volumes":[21]},{"term":"Asymptomatic","definition":"Showing no symptoms despite having a condition.","volumes":[21]},{"term":"Ataxia","definition":"Impaired coordination, affecting limbs, gait, speech or eye movements.","volumes":[25]},{"term":"Atmosphere","definition":"The layer of air around Earth; atmospheric pressure affects breathing at altitude.","volumes":[21]},{"term":"Atopic Dermatitis (Eczema)","definition":"A chronic relapsing inflammatory skin disease characterized by intense pruritus, xerosis, barrier defects, and immune dysregulation.","volumes":[16]},{"term":"Atopy","definition":"A tendency to develop allergic conditions such as eczema, asthma, hay fever and food allergy.","volumes":[9]},{"term":"Atopy","definition":"A tendency to develop allergic conditions such as eczema, rhinitis or asthma.","volumes":[21]},{"term":"ATP","definition":"Adenosine triphosphate, the main energy-carrying molecule of cells.","volumes":[25]},{"term":"ATP (adenosine triphosphate)","definition":"The immediate energy currency of cells. Muscle contraction, nerve signalling and many processes run directly on ATP, which the body constantly regenerates.","volumes":[14]},{"term":"Audiogram","definition":"A chart of hearing thresholds across frequencies, usually shown with frequency on the horizontal axis and hearing level in decibels on the vertical axis.","volumes":[28]},{"term":"Audiologist","definition":"A health professional who assesses hearing, tinnitus and communication needs and provides rehabilitation, devices and support. Training and regulation vary by country.","volumes":[28]},{"term":"Auditory brainstem response (ABR)","definition":"A test that records electrical activity from the hearing pathway in response to sound. It can estimate hearing in infants or people who cannot complete behavioural testing.","volumes":[28]},{"term":"Auditory nerve","definition":"The nerve that carries electrical signals from the cochlea to the brainstem.","volumes":[28]},{"term":"Auditory processing","definition":"The brain’s analysis of sound, including speech, timing, localisation, attention and pattern recognition.","volumes":[28]},{"term":"Augmentative and alternative communication","definition":"Methods such as symbol boards or speech devices that support communication.","volumes":[25]},{"term":"Aura","definition":"Reversible focal neurological symptoms, such as visual changes, that can occur with migraine.","volumes":[25]},{"term":"Auricle","definition":"The visible outer ear, also called the pinna. It collects and shapes sound entering the ear canal.","volumes":[28]},{"term":"Autism","definition":"A neurodevelopmental profile involving differences in social communication and sensory processing, with varied support needs.","volumes":[25]},{"term":"Auto-injector","definition":"A prefilled device that delivers a dose of epinephrine, used according to the prescriber's training and the individual's plan.","volumes":[9]},{"term":"Autoimmune","definition":"When the immune system mistakenly attacks the body's own tissues.","volumes":[21]},{"term":"Autonomic dysreflexia","definition":"A dangerous autonomic response to a noxious trigger in people with high-level spinal cord injury.","volumes":[25]},{"term":"Autonomic ganglion","definition":"A relay cluster where preganglionic autonomic fibres synapse with postganglionic neurons.","volumes":[25]},{"term":"Autonomic nervous system","definition":"The part of the nervous system regulating involuntary functions such as heart rate, breathing and digestion.","volumes":[13]},{"term":"Autonomic tone","definition":"The ongoing baseline balance of autonomic influence on an organ.","volumes":[25]},{"term":"Autorefraction","definition":"An automated estimate of refractive error that may be refined by a clinician.","volumes":[26]},{"term":"Avoidance","definition":"Staying away from situations, thoughts or feelings. Can give short relief but may maintain stress when persistent.","volumes":[13]},{"term":"Axis","definition":"The orientation in degrees of the cylindrical correction in a spectacle prescription.","volumes":[26]},{"term":"Axon","definition":"The long projection of a neuron that carries electrical signals away from the cell body.","volumes":[25]},{"term":"Axon terminal","definition":"The ending of an axon where neurotransmitter is released.","volumes":[25]},{"term":"Azelaic Acid","definition":"A naturally occurring dicarboxylic acid with antibacterial, comedolytic, anti-inflammatory, and tyrosinase-inhibiting properties.","volumes":[16]},{"term":"Bacteria","definition":"Single-celled organisms; some cause respiratory infections.","volumes":[21]},{"term":"Bacteria","definition":"Single-celled microorganisms, some of which can cause infection.","volumes":[26]},{"term":"Balance","definition":"The ability to keep the body's centre of mass over its base of support, statically or while moving. Trainable at any age.","volumes":[14]},{"term":"Ballistic stretching","definition":"Bouncing, momentum-driven stretching beyond the comfortable range. Generally discouraged because it can trigger stretch reflexes and strain tissue.","volumes":[14]},{"term":"Bark","definition":"The outer protective layer of a woody stem or branch. Cinnamon is made from the inner bark.","volumes":[3]},{"term":"Baroreceptor","definition":"A stretch-sensitive receptor that contributes to blood-pressure regulation.","volumes":[25]},{"term":"Barotrauma","definition":"Injury caused by a rapid pressure change, such as during diving, air travel or an explosion. It can affect the eardrum, middle ear or inner ear.","volumes":[28]},{"term":"Barrel chest","definition":"A rounded chest shape sometimes seen with chronic air trapping.","volumes":[21]},{"term":"Basal Cell Carcinoma (BCC)","definition":"The most frequent form of human skin cancer, arising from basal cells in the epidermis, usually presenting as a pearly or translucent papule.","volumes":[16]},{"term":"Basal ganglia","definition":"Deep brain structures involved in initiating and smoothing movement, alongside the cerebellum and motor cortex.","volumes":[14]},{"term":"Basal ganglia","definition":"Deep grey-matter structures involved in action selection, habit learning and movement regulation.","volumes":[25]},{"term":"Basal metabolic rate (BMR)","definition":"The energy the body uses at complete rest to maintain vital functions. A component of total daily energy expenditure.","volumes":[14]},{"term":"Baseline","definition":"A person's usual state, used to judge change.","volumes":[21]},{"term":"Basophil","definition":"A type of white blood cell that, like mast cells, can release histamine during an allergic reaction.","volumes":[9]},{"term":"Beau’s Lines","definition":"Horizontal, transverse grooves or depressions across the nail plate resulting from temporary interruption of cell division in the matrix.","volumes":[16]},{"term":"Benign paroxysmal positional vertigo (BPPV)","definition":"A common vestibular disorder in which brief spinning is triggered by specific head-position changes. Diagnosis depends on positional eye-movement findings.","volumes":[28]},{"term":"Benzoyl Peroxide","definition":"A topical antimicrobial agent that releases free-radical oxygen inside sebaceous follicles, killing Cutibacterium acnes without inducing bacterial resistance.","volumes":[16]},{"term":"Beta Hydroxy Acid (Salicylic Acid)","definition":"A lipid-soluble phenolic acid that penetrates inside sebaceous follicles to dissolve oily debris, unclog pores, and reduce mild inflammation.","volumes":[16]},{"term":"Beta-carotene","definition":"A plant pigment that the body can convert to vitamin A.","volumes":[26]},{"term":"Bicarbonate","definition":"The main transported form of carbon dioxide; key to acid-base balance.","volumes":[21]},{"term":"Bifocal","definition":"A lens with separate regions for two viewing distances.","volumes":[26]},{"term":"Binocular disparity","definition":"The small difference between the images seen by the two eyes.","volumes":[26]},{"term":"Bioavailability","definition":"The extent to which a nutrient is absorbed and available for use by the body.","volumes":[25]},{"term":"Biofeedback","definition":"Methods that show physiological signals such as heart rate so people can learn to notice them. Evidence varies by application.","volumes":[13]},{"term":"Biomarker","definition":"A measurable biological indicator associated with a process or condition, often imperfect on its own.","volumes":[25]},{"term":"Biomass","definition":"Organic material such as wood or crop residue burned for fuel, producing smoke.","volumes":[21]},{"term":"Biomechanics","definition":"The study of the mechanical principles of human movement — forces, levers, motion and their effects on the body.","volumes":[14]},{"term":"Biotin (Vitamin B7)","definition":"A water-soluble B vitamin serving as a coenzyme in carboxylase enzymes needed for fatty acid and branched-chain amino acid metabolism.","volumes":[16]},{"term":"Biphasic reaction","definition":"A second wave of allergic symptoms that can occur after the first has apparently resolved. One reason for medical observation after a serious reaction.","volumes":[9]},{"term":"Blepharitis","definition":"Inflammation of the eyelid margins.","volumes":[26]},{"term":"Blind spot","definition":"An area without visual sensitivity corresponding in each eye to the optic disc.","volumes":[26]},{"term":"Blindness","definition":"A term describing severe visual impairment, with definitions that vary by jurisdiction.","volumes":[26]},{"term":"Blood pressure","definition":"The force of blood against artery walls. Rises temporarily during stress; sustained high readings need medical assessment.","volumes":[13]},{"term":"Blood pressure","definition":"The force of blood against artery walls; linked to heart and lung health.","volumes":[21]},{"term":"Blood-brain barrier","definition":"A protective filter between blood and brain tissue.","volumes":[21]},{"term":"Blood-brain barrier","definition":"A selectively permeable interface between the blood and brain tissue that regulates exchange.","volumes":[25]},{"term":"BMI (body mass index)","definition":"Weight (kg) divided by height (m) squared. A population screening tool — not a measure of individual health or worth.","volumes":[14]},{"term":"Body composition","definition":"The relative proportions of fat, muscle, bone and water in the body. One health-related measure among many — never a measure of worth.","volumes":[14]},{"term":"Body scan","definition":"A guided attention practice moving through body areas. Can be stopped at any time.","volumes":[13]},{"term":"Bone-conduction hearing device","definition":"A device that sends vibration through the skull to stimulate the inner ear, bypassing the outer or middle ear.","volumes":[28]},{"term":"Botanical family","definition":"A group of related genera that share structural features, such as Lamiaceae (the mint family) or Apiaceae (the carrot family).","volumes":[3]},{"term":"Botulinum Toxin","definition":"A neurotoxic protein injected by licensed medical professionals that temporarily blocks neuromuscular acetylcholine release to relax hyperactive muscles.","volumes":[16]},{"term":"Boundary","definition":"A limit that protects time, energy, space, safety or values.","volumes":[13]},{"term":"Boyle's law","definition":"The principle that gas pressure falls as volume rises, underlying breathing mechanics.","volumes":[21]},{"term":"Bradykinesia","definition":"Slowness and reduced amplitude of voluntary movement.","volumes":[25]},{"term":"Bradypnoea","definition":"Abnormally slow breathing.","volumes":[21]},{"term":"Braille","definition":"A tactile reading and writing system based on patterns of raised dots.","volumes":[26]},{"term":"Brain tumour","definition":"A growth of abnormal cells in the brain, which may be benign or malignant.","volumes":[25]},{"term":"Brainstem","definition":"The lower brain region that automatically controls breathing rhythm.","volumes":[21]},{"term":"Brainstem","definition":"The midbrain, pons and medulla, connecting the brain and spinal cord and supporting vital functions.","volumes":[25]},{"term":"Breath holding","definition":"Stopping breathing deliberately. Not recommended for beginners and may be unsafe for some people.","volumes":[13]},{"term":"Breathlessness","definition":"The subjective feeling of difficult or inadequate breathing (dyspnoea).","volumes":[21]},{"term":"Broad-Spectrum UV Protection","definition":"Sunscreen formulations proven to protect against both UVB radiation (burning) and UVA radiation (deep penetration, photoaging, and DNA alteration).","volumes":[16]},{"term":"Bronchi","definition":"The two main airways branching from the trachea into the lungs.","volumes":[21]},{"term":"Bronchial tree","definition":"The branching system of airways from trachea to bronchioles.","volumes":[21]},{"term":"Bronchiectasis","definition":"Permanent widening and damage of the bronchi impairing mucus clearance.","volumes":[21]},{"term":"Bronchioles","definition":"The smallest airways, lacking cartilage, ending in alveoli.","volumes":[21]},{"term":"Bronchiolitis","definition":"Viral inflammation of small airways in infants.","volumes":[21]},{"term":"Bronchitis","definition":"Inflammation of the bronchi; acute (usually viral) or chronic (in COPD).","volumes":[21]},{"term":"Bronchoconstriction","definition":"Narrowing of airways by smooth-muscle tightening.","volumes":[21]},{"term":"Bronchodilator","definition":"A medicine that relaxes airway muscle to widen airways.","volumes":[21]},{"term":"Bronchospasm","definition":"Sudden tightening of airway muscle causing narrowing.","volumes":[21]},{"term":"Bulb","definition":"A short underground stem surrounded by fleshy storage leaves, as in onion and garlic.","volumes":[3]},{"term":"Burnout","definition":"The WHO describes burn-out as an occupational phenomenon from chronic workplace stress that has not been successfully managed. It involves exhaustion, mental distance and reduced efficacy.","volumes":[13]},{"term":"Burnout risk factor","definition":"Workplace features such as high demands and low control that are linked to burnout.","volumes":[13]},{"term":"Caffeine","definition":"A stimulant found in coffee, tea and other products. May affect sleep and anxiety in some people.","volumes":[13]},{"term":"Canal of Schlemm","definition":"A channel involved in drainage of aqueous humour from the eye.","volumes":[26]},{"term":"Capillary","definition":"The smallest blood vessel, where oxygen and nutrients exchange with tissues. Density increases in trained muscle.","volumes":[14]},{"term":"Capillary","definition":"The smallest blood vessel; in lungs it wraps the alveoli for gas exchange.","volumes":[21]},{"term":"Captioning","definition":"Text that displays spoken and non-speech audio information. Captions can be live, automated or pre-recorded and support access in many settings.","volumes":[28]},{"term":"Carbon dioxide (CO2)","definition":"The main gaseous waste product of energy use, removed by the lungs.","volumes":[21]},{"term":"Carbonic anhydrase","definition":"An enzyme that converts CO2 and water into bicarbonate rapidly.","volumes":[21]},{"term":"Cardiac","definition":"Relating to the heart.","volumes":[21]},{"term":"Cardiac output","definition":"The volume of blood the heart pumps per minute — heart rate × stroke volume. Rises several-fold during exercise.","volumes":[14]},{"term":"Cardiopulmonary","definition":"Relating jointly to the heart and lungs.","volumes":[21]},{"term":"Cardiorespiratory fitness","definition":"See cardiovascular endurance — the capacity of heart, lungs and vessels to sustain activity.","volumes":[14]},{"term":"Cardiovascular endurance","definition":"The ability of the heart, lungs and circulation to supply oxygen during sustained physical activity.","volumes":[14]},{"term":"Caregiver strain","definition":"Physical, emotional and financial pressure experienced by people who provide ongoing care.","volumes":[13]},{"term":"Carotenoid","definition":"A family of pigments found in plants and other organisms, including lutein and beta-carotene.","volumes":[26]},{"term":"Cartilage","definition":"Smooth, firm connective tissue covering the ends of bones in synovial joints; cushions and reduces friction. Nourished by movement.","volumes":[14]},{"term":"Cartilage","definition":"Firm tissue that supports the larger airways and keeps them open.","volumes":[21]},{"term":"Casein","definition":"The main group of proteins in milk, which can trigger milk allergy.","volumes":[9]},{"term":"Cassia","definition":"Cinnamon-flavoured bark from several Cinnamomum species other than Cinnamomum verum. Usually thicker, darker and stronger.","volumes":[3]},{"term":"Catagen Phase","definition":"The brief involutional transitional phase lasting 2 to 3 weeks where cell division ceases and the hair bulb detaches from the dermal papilla.","volumes":[16]},{"term":"Catastrophising","definition":"Expecting the worst possible outcome. A thinking pattern often found in worry.","volumes":[13]},{"term":"Celiac disease","definition":"An autoimmune condition triggered by gluten in genetically susceptible people. It damages the lining of the small intestine and is diagnosed by clinicians.","volumes":[9]},{"term":"Cell","definition":"The basic unit of life; cells need oxygen to make energy.","volumes":[21]},{"term":"Cellular respiration","definition":"The cellular process that uses oxygen to release energy from nutrients.","volumes":[21]},{"term":"Centella Asiatica (Cica)","definition":"A botanical extract containing active triterpenoids (asiaticoside, madecassoside) that support wound repair and decrease cutaneous inflammatory markers.","volumes":[16]},{"term":"Central nervous system","definition":"The brain and spinal cord.","volumes":[13]},{"term":"Central sensitisation","definition":"Increased responsiveness of central pain pathways, contributing to amplified pain.","volumes":[25]},{"term":"Central sleep apnoea","definition":"Apnoea from failed brain signalling of breathing, not airway blockage.","volumes":[21]},{"term":"Central vision","definition":"The part of the visual field used when looking directly at something.","volumes":[26]},{"term":"Ceramides","definition":"A family of waxy lipid molecules consisting of sphingosine and a fatty acid, making up roughly 50% of the stratum corneum intercellular lipid matrix.","volumes":[16]},{"term":"Cereals containing gluten","definition":"Regulatory term used in the EU, UK and elsewhere for wheat, rye, barley, oats and their hybrids.","volumes":[9]},{"term":"Cerebellum","definition":"A hindbrain structure important for coordination, timing, balance and motor learning.","volumes":[25]},{"term":"Cerebral cortex","definition":"The folded outer layer of grey matter of the cerebral hemispheres.","volumes":[25]},{"term":"Cerebral palsy","definition":"A group of movement and posture disorders arising from early brain injury or maldevelopment.","volumes":[25]},{"term":"Cerebrospinal fluid","definition":"Clear fluid that cushions the central nervous system and circulates through the ventricles.","volumes":[25]},{"term":"Cerumen","definition":"The medical term for earwax. It protects the ear canal, repels some water and helps remove debris.","volumes":[28]},{"term":"Chemical Peel","definition":"Application of a chemical exfoliating agent (glycolic, salicylic, or TCA) to cause controlled destruction of epidermal or dermal layers.","volumes":[16]},{"term":"Chemoreceptor","definition":"A sensor detecting chemicals such as CO2, oxygen and pH to adjust breathing.","volumes":[21]},{"term":"Chemoreceptor","definition":"A receptor that detects chemical compounds or changes such as carbon dioxide.","volumes":[25]},{"term":"Chiasm","definition":"The junction at which some optic nerve fibres cross to the opposite side.","volumes":[26]},{"term":"Cholesteatoma","definition":"An abnormal collection of skin-like tissue in the middle ear or mastoid that can enlarge and erode bone. Usually treated surgically.","volumes":[28]},{"term":"Choline","definition":"A nutrient involved in membrane structure and acetylcholine synthesis.","volumes":[25]},{"term":"Choroid","definition":"A vascular layer between the retina and sclera that helps supply the outer retina.","volumes":[26]},{"term":"Chronic","definition":"Long-lasting, typically months or years.","volumes":[21]},{"term":"Chronic bronchitis","definition":"In COPD, a chronic productive cough for at least three months in two years.","volumes":[21]},{"term":"Chronic obstructive pulmonary disease (COPD)","definition":"Persistent, progressive airflow limitation from irritant exposure.","volumes":[21]},{"term":"Chronic stress","definition":"Stress that persists over weeks or months, with limited recovery.","volumes":[13]},{"term":"Cilia","definition":"Tiny hair-like projections that beat to move mucus upward.","volumes":[21]},{"term":"Ciliary body","definition":"Tissue behind the iris that produces aqueous humour and helps control lens shape.","volumes":[26]},{"term":"Ciliary dyskinesia","definition":"A condition where cilia do not beat properly, impairing clearance.","volumes":[21]},{"term":"Ciliary muscle","definition":"A muscle that changes tension on lens fibres during accommodation.","volumes":[26]},{"term":"Circadian Clock Genes","definition":"Intracellular molecular oscillators in skin cells that orchestrate 24-hour cycles of barrier repair, hydration, and mitotic renewal.","volumes":[16]},{"term":"Circadian rhythm","definition":"The roughly 24-hour biological cycle influencing sleep, hormones and alertness.","volumes":[13]},{"term":"Circadian rhythm","definition":"The body's roughly 24-hour internal clock, which influences sleep, hormones and performance timing.","volumes":[14]},{"term":"Circadian rhythm","definition":"An approximately 24-hour biological cycle affecting sleep, temperature and many functions.","volumes":[25]},{"term":"Circulatory system","definition":"The heart, blood and vessels that transport gases and nutrients.","volumes":[21]},{"term":"Clean Beauty (Marketing Term)","definition":"An unregulated marketing term with no legal or scientific definition, frequently relying on chemophobic fear-based advertising.","volumes":[16]},{"term":"Climate change","definition":"Long-term shifts in weather patterns affecting allergens, smoke and heat.","volumes":[21]},{"term":"Clinical","definition":"Relating to the observation and treatment of patients by clinicians.","volumes":[21]},{"term":"Clinical guideline","definition":"Evidence-informed recommendations for care in defined circumstances and jurisdictions.","volumes":[25]},{"term":"Clinical guideline","definition":"A systematically developed set of recommendations to support care decisions.","volumes":[26]},{"term":"Closed kinetic chain","definition":"An exercise where the moving limb's end is fixed — e.g. a push-up or squat; generally joint-friendly.","volumes":[14]},{"term":"Co-factor","definition":"A circumstance such as exercise, illness, alcohol or certain medicines that may make reactions more likely or more severe in some people.","volumes":[9]},{"term":"Coal Tar","definition":"A byproduct of coal processing with kerato-plastic, antipruritic, and mild antiseptic properties used for scalp psoriasis and severe eczema.","volumes":[16]},{"term":"Cochlea","definition":"The spiral inner-ear structure that converts sound into neural signals.","volumes":[25]},{"term":"Cochlea","definition":"The fluid-filled, spiral-shaped hearing organ of the inner ear. It contains sensory hair cells that convert sound vibration into nerve signals.","volumes":[28]},{"term":"Cochlear implant","definition":"An electronic device for selected people with severe hearing loss. It bypasses damaged hair cells and stimulates the auditory nerve.","volumes":[28]},{"term":"Codex Alimentarius","definition":"The international food standards body established by FAO and WHO, publishing standards and codes of practice used as reference by many countries.","volumes":[9]},{"term":"Cofactor","definition":"A molecule or ion required for an enzyme to work.","volumes":[25]},{"term":"Cognitive behavioural therapy (CBT)","definition":"A structured psychological therapy linking thoughts, feelings and behaviour. Delivered by trained professionals.","volumes":[13]},{"term":"Cognitive distortion","definition":"A habitual pattern of biased thinking, such as all-or-nothing reasoning.","volumes":[13]},{"term":"Cognitive load","definition":"The mental effort required by a task. High load can make decisions harder.","volumes":[13]},{"term":"Cognitive reappraisal","definition":"Reinterpreting a situation to change its emotional impact.","volumes":[13]},{"term":"Cognitive reserve","definition":"The ability to maintain cognitive function despite brain change, shaped by experience and health.","volumes":[25]},{"term":"Collagen","definition":"The most abundant structural protein in the dermis, organizing into triple-helix fibrils that provide tensile strength and firmness.","volumes":[16]},{"term":"Collateral ventilation","definition":"Air movement between airways through alternate routes.","volumes":[21]},{"term":"Colloidal Oatmeal","definition":"Finely ground whole oat grains containing beta-glucans, avenanthramides, and lipids approved as an over-the-counter skin protectant.","volumes":[16]},{"term":"Colour contrast","definition":"The visual difference between colours or their brightness that can help distinguish elements.","volumes":[26]},{"term":"Colourism","definition":"Prejudice or discrimination against individuals with darker skin tones, typically among people of the same ethnic or racial group.","volumes":[16]},{"term":"Comedogenicity","definition":"The potential of an ingredient or formulation to induce follicular hyperkeratosis and plug pores, forming comedones.","volumes":[16]},{"term":"Comedone","definition":"A clogged hair follicle pore. An open comedone is a blackhead (darkened by melanin and lipid oxidation); a closed comedone is a whitehead.","volumes":[16]},{"term":"Comorbidity","definition":"An additional condition occurring alongside a primary condition.","volumes":[25]},{"term":"Compassion fatigue","definition":"Emotional exhaustion from continual care for others. Related to but distinct from burnout.","volumes":[13]},{"term":"Compliance","definition":"How easily the lungs stretch under pressure; low compliance means stiff lungs.","volumes":[21]},{"term":"Computed tomography (CT)","definition":"Detailed cross-sectional imaging of the body.","volumes":[21]},{"term":"Concentric contraction","definition":"A muscle action in which the muscle shortens while producing force — e.g. lifting a weight upward.","volumes":[14]},{"term":"Concussion","definition":"A clinical diagnosis of mild traumatic brain injury, with temporary functional disturbance.","volumes":[25]},{"term":"Conductive hearing loss","definition":"Reduced hearing because sound is not transmitted efficiently through the outer or middle ear—for example because of wax, fluid or a structural problem.","volumes":[28]},{"term":"Cone","definition":"A retinal photoreceptor supporting colour and detailed vision in brighter light.","volumes":[25]},{"term":"Cones","definition":"Retinal photoreceptors important for daylight vision, colour and fine detail.","volumes":[26]},{"term":"Confounding","definition":"A factor that distorts an apparent link between two things.","volumes":[21]},{"term":"Congestion","definition":"Blockage or fluid build-up, such as in nasal or chest congestion.","volumes":[21]},{"term":"Conjunctiva","definition":"A thin membrane covering the inner eyelids and the front of the sclera.","volumes":[26]},{"term":"Consolidation","definition":"Filling of alveoli with fluid or pus, as in pneumonia.","volumes":[21]},{"term":"Continuous positive airway pressure (CPAP)","definition":"A prescribed device keeping the airway open during sleep.","volumes":[21]},{"term":"Contracture","definition":"Persistent shortening of muscle or connective tissue that restricts movement.","volumes":[25]},{"term":"Controlled breathing","definition":"Deliberate breathing techniques taught for symptom management.","volumes":[21]},{"term":"Convergence","definition":"Inward rotation of the eyes when viewing a near target.","volumes":[26]},{"term":"Cool-down","definition":"A gradual ease-down after exercise — light activity and gentle stretching — to transition the body back to rest.","volumes":[14]},{"term":"Coordination","definition":"The ability to use the right muscles at the right time with appropriate sequencing and timing for smooth, accurate movement.","volumes":[14]},{"term":"Coping strategy","definition":"Any thought or action used to manage demands. Coping can be helpful, mixed or unhelpful depending on context.","volumes":[13]},{"term":"Core","definition":"The muscle cylinder around the trunk — abdominals, obliques, transverse abdominis, multifidus, diaphragm and pelvic floor — that stabilises the spine and manages pressure.","volumes":[14]},{"term":"Corneal abrasion","definition":"A scratch or defect in the surface layer of the cornea.","volumes":[26]},{"term":"Corneal endothelium","definition":"The inner cell layer that helps regulate corneal hydration and transparency.","volumes":[26]},{"term":"Corneal epithelium","definition":"The outer layer of cells covering the cornea.","volumes":[26]},{"term":"Corneal stroma","definition":"The thick central layer of the cornea, made largely of organised collagen.","volumes":[26]},{"term":"Corneal topography","definition":"Mapping the curvature of the front surface of the cornea.","volumes":[26]},{"term":"Corneocyte","definition":"A terminally differentiated, anucleated keratinocyte in the stratum corneum packed with insoluble keratin protein.","volumes":[16]},{"term":"Corpus callosum","definition":"The large bundle of fibres connecting the two cerebral hemispheres.","volumes":[25]},{"term":"Cortex","definition":"The brain's outer layer allowing some voluntary breathing control.","volumes":[21]},{"term":"Corticosteroid","definition":"An anti-inflammatory medicine; inhaled forms treat airway inflammation.","volumes":[21]},{"term":"Corticotropin-releasing hormone (CRH)","definition":"A hypothalamic hormone that starts the HPA-axis cascade.","volumes":[13]},{"term":"Cortisol","definition":"The main glucocorticoid in humans. Supports energy mobilisation and regulates many systems. Levels follow a daily rhythm.","volumes":[13]},{"term":"Cortisol","definition":"The primary glucocorticoid stress hormone synthesized by the adrenal cortex; suppresses collagen production and degrades barrier lipids at chronic high levels.","volumes":[16]},{"term":"Cortisol","definition":"A steroid hormone involved in glucose regulation, stress and immune modulation.","volumes":[25]},{"term":"Cortisol awakening response","definition":"A rise in cortisol in the first 30–45 minutes after waking. Its meaning is still debated.","volumes":[13]},{"term":"Cough","definition":"A protective reflex that expels air to clear the airways.","volumes":[21]},{"term":"Cradle Cap (Infantile Seborrhoeic Dermatitis)","definition":"A harmless, temporary scalp condition in newborns and infants causing greasy, yellow, crusty scales.","volumes":[16]},{"term":"Cranial nerve","definition":"One of twelve pairs of nerves emerging from the brain or brainstem.","volumes":[25]},{"term":"Cranial nerve examination","definition":"Assessment of functions such as vision, eye movement, facial strength, hearing and swallowing.","volumes":[25]},{"term":"Crisis line","definition":"A service offering immediate telephone or text support during distress. Availability varies by country.","volumes":[13]},{"term":"Cross-contact","definition":"The unintentional transfer of an allergen from a food that contains it to one that does not, via surfaces, utensils, hands, oils or air.","volumes":[9]},{"term":"Cross-contamination (microbial)","definition":"The transfer of harmful microorganisms between foods, surfaces or hands. A food-hygiene issue distinct from allergen cross-contact.","volumes":[9]},{"term":"Cross-reactivity","definition":"When the immune system reacts to similar proteins in different foods or pollens.","volumes":[9]},{"term":"Cross-training","definition":"Using varied activities to train the same fitness while reducing repetitive overload — e.g. swimming for a runner.","volumes":[14]},{"term":"Croup","definition":"Childhood viral illness causing a barking cough and noisy breathing.","volumes":[21]},{"term":"Crustaceans","definition":"A group of shellfish with segmented bodies and shells, including prawns/shrimp, crab, lobster and crayfish.","volumes":[9]},{"term":"CT scan","definition":"Computed tomography, a fast X-ray-based imaging method useful for acute bleeding and trauma.","volumes":[25]},{"term":"Cultivar","definition":"A cultivated plant variety selected and maintained for particular traits, written in single quotation marks, for example Ocimum basilicum 'Genovese'.","volumes":[3]},{"term":"Cutibacterium acnes (C. acnes)","definition":"An anaerobic commensal bacterium residing within sebaceous follicles; plays a role in acne pathophysiology through proinflammatory enzyme release.","volumes":[16]},{"term":"Cyanosis","definition":"Bluish colour of lips or skin from low oxygen; a warning sign.","volumes":[21]},{"term":"Cylinder","definition":"The component of an optical prescription used to correct astigmatism.","volumes":[26]},{"term":"Dandruff (Pityriasis Capitis)","definition":"The mild, non-inflammatory end of the seborrhoeic dermatitis spectrum characterized by uninflamed, visible white flaking of scalp corneocytes.","volumes":[16]},{"term":"Dark adaptation","definition":"The gradual adjustment of visual sensitivity after moving into low light.","volumes":[26]},{"term":"Dead space","definition":"Air that reaches alveoli but does not take part in gas exchange.","volumes":[21]},{"term":"Deaf culture","definition":"The language, identity, history and community of Deaf people, often centred around sign language and shared experience. It is not defined by deficiency.","volumes":[28]},{"term":"Decibel (dB)","definition":"A unit used to compare sound levels or hearing thresholds. In hearing tests, dB HL describes hearing level; environmental dB SPL describes physical sound pressure.","volumes":[28]},{"term":"Decision fatigue","definition":"A proposed reduction in decision quality after many decisions. Evidence is debated.","volumes":[13]},{"term":"Decoction","definition":"A liquid made by simmering tougher plant parts (roots, bark, seeds) in water for a period. A technical term used in food and herbal contexts.","volumes":[3]},{"term":"Deficiency","definition":"An insufficient intake or supply of a nutrient or other essential factor.","volumes":[25]},{"term":"Delayed-onset muscle soreness (DOMS)","definition":"Muscle aching and stiffness peaking 24–72 hours after unaccustomed exercise, especially eccentric work. Temporary; not required for progress.","volumes":[14]},{"term":"Delirium","definition":"An acute disturbance of attention and awareness, often caused by illness or medication.","volumes":[25]},{"term":"Deload","definition":"A planned reduction in training volume or load (typically a week at 50–70% of usual) to dissipate fatigue and consolidate adaptation.","volumes":[14]},{"term":"Dementia","definition":"A syndrome of cognitive decline severe enough to affect everyday function.","volumes":[25]},{"term":"Demodex Folliculorum","definition":"Microscopic commensal mites that inhabit human pilosebaceous units, particularly on facial skin.","volumes":[16]},{"term":"Demyelination","definition":"Loss or damage of myelin, impairing nerve signal conduction.","volumes":[25]},{"term":"Dendrite","definition":"A branched neuronal process that receives synaptic input.","volumes":[25]},{"term":"Deodorant","definition":"A personal-care formulation containing antimicrobial agents and fragrance to neutralize or cover bacterial odor without stopping sweat production.","volumes":[16]},{"term":"Depolarisation","definition":"A shift in membrane potential toward a less negative or positive value.","volumes":[25]},{"term":"Depression","definition":"A clinical mood disorder with persistent low mood, loss of interest and other symptoms. Requires professional assessment.","volumes":[13]},{"term":"Depth perception","definition":"The interpretation of spatial distance using visual and other cues.","volumes":[26]},{"term":"Dermal Fillers","definition":"Gel-like substances (predominantly cross-linked hyaluronic acid) injected to restore lost soft-tissue volume and contour facial structures.","volumes":[16]},{"term":"Dermal Papillae","definition":"Finger-like projections of the dermis that interlock with epidermal ridges, enhancing mechanical adhesion and nutrient exchange.","volumes":[16]},{"term":"Dermatome","definition":"The region of skin associated mainly with one spinal nerve root.","volumes":[25]},{"term":"Dermis","definition":"The supportive middle layer of skin beneath the epidermis, rich in collagen, elastin fibers, blood vessels, nerve endings, and hair follicles.","volumes":[16]},{"term":"Desquamation","definition":"The enzymatic, physiological shedding of corneocytes from the outer surface of the stratum corneum.","volumes":[16]},{"term":"Detraining","definition":"The partial loss of training adaptations during prolonged inactivity — gradual, and reversible on return.","volumes":[14]},{"term":"Developmental milestone","definition":"A skill usually acquired within an approximate age range, with normal variation.","volumes":[25]},{"term":"DHA","definition":"Docosahexaenoic acid, a long-chain omega-3 fatty acid enriched in neural membranes.","volumes":[25]},{"term":"Diabetic macular oedema","definition":"Swelling of the macula related to damage of retinal blood vessels in diabetes.","volumes":[26]},{"term":"Diagnosis","definition":"The identification of a disease by a qualified clinician.","volumes":[21]},{"term":"Diaphragm","definition":"The main breathing muscle; also a key component of the core cylinder for pressure management.","volumes":[14]},{"term":"Diaphragm","definition":"The main muscle of breathing beneath the lungs.","volumes":[21]},{"term":"Diaphragmatic breathing","definition":"Breathing that moves the belly as the diaphragm descends. Often practised as slow, comfortable breathing.","volumes":[13]},{"term":"Dietitian (registered)","definition":"A qualified health professional who assesses nutrition and provides dietary guidance. Titles and regulation vary by country.","volumes":[9]},{"term":"Diffusion","definition":"Passive movement of gas from higher to lower partial pressure.","volumes":[21]},{"term":"Digital overload","definition":"Feeling overwhelmed by notifications, information volume or constant connectivity.","volumes":[13]},{"term":"Dilation","definition":"Enlargement of the pupil, sometimes produced with examination drops.","volumes":[26]},{"term":"Dimethicone","definition":"A silicone-based polymer providing a breathable, non-comedogenic protective film that locks in moisture and prevents chafing.","volumes":[16]},{"term":"Dioptre","definition":"A unit used to describe the optical power of a lens.","volumes":[26]},{"term":"Diplopia","definition":"Double vision, or seeing two images of one object.","volumes":[26]},{"term":"Disinfecting solution","definition":"A product formulated to reduce microorganisms on reusable contact lenses when used as directed.","volumes":[26]},{"term":"Dissociation","definition":"A disconnection from thoughts, feelings, body or surroundings. Can occur with trauma and should be discussed with professionals.","volumes":[13]},{"term":"Distal","definition":"Further from the centre or point of origin, e.g., distal airways.","volumes":[21]},{"term":"Disulfide Bond","definition":"Strong covalent chemical bonds between sulfur atoms in cystine amino acids that give keratin fibers their structural rigidity and shape.","volumes":[16]},{"term":"DOMS","definition":"See delayed-onset muscle soreness.","volumes":[14]},{"term":"Dopamine","definition":"A neurotransmitter involved in movement, reward learning and multiple regulatory processes.","volumes":[25]},{"term":"Dorsal horn","definition":"The sensory-receiving region of spinal grey matter.","volumes":[25]},{"term":"Dorsal root ganglion","definition":"A cluster of sensory neuron cell bodies outside the spinal cord.","volumes":[25]},{"term":"Dose-response","definition":"The relationship where increasing amounts of activity are associated with increasing benefit up to a plateau — the basis of activity guidance.","volumes":[14]},{"term":"Double Cleansing","definition":"A two-step evening cleansing technique utilizing an oil-based cleanser first to melt sunscreen and sebum, followed by a water-based cleanser.","volumes":[16]},{"term":"Drupe","definition":"A fleshy fruit with a hard stone enclosing the seed, such as a cherry or peppercorn.","volumes":[3]},{"term":"Drusen","definition":"Deposits beneath the retina that can be seen in age-related macular degeneration.","volumes":[26]},{"term":"Dry AMD","definition":"A form of age-related macular degeneration that does not involve the abnormal vessels of wet AMD.","volumes":[26]},{"term":"Dynamic stretching","definition":"Controlled movement through a joint's range of motion — the preferred stretching style in warm-ups.","volumes":[14]},{"term":"Dysautonomia","definition":"A general term for abnormal autonomic function from any cause.","volumes":[25]},{"term":"Dysbiosis","definition":"Imbalance in the normal microbial community.","volumes":[21]},{"term":"Dyslexia","definition":"A specific learning difference affecting accurate and fluent word reading and spelling.","volumes":[25]},{"term":"Dysphagia","definition":"Difficulty swallowing, which can lead to choking or aspiration.","volumes":[25]},{"term":"Dyspnoea","definition":"The subjective feeling of breathlessness.","volumes":[21]},{"term":"Ear canal","definition":"The passage from the outer ear to the eardrum. It is lined with skin and wax glands and usually self-cleans.","volumes":[28]},{"term":"Eardrum","definition":"The tympanic membrane. It vibrates in response to sound and separates the outer-ear canal from the middle ear.","volumes":[28]},{"term":"Early intervention","definition":"Support or therapy provided when developmental concerns are first identified.","volumes":[25]},{"term":"Earwax impaction","definition":"A build-up of wax that blocks the ear canal and causes symptoms such as fullness or hearing change. Removal should be done safely by a trained professional.","volumes":[28]},{"term":"Eccentric contraction","definition":"A muscle action in which the muscle lengthens while producing force — e.g. slowly lowering a weight. High force, key for control and soreness.","volumes":[14]},{"term":"Eccentric overload","definition":"Emphasising the lengthening phase of a lift; potent for strength and muscle damage — progress it gradually.","volumes":[14]},{"term":"Eccrine Gland","definition":"The most numerous sweat glands, found all over the body, secreting clear, dilute watery sweat directly onto the skin for thermoregulation.","volumes":[16]},{"term":"Edema","definition":"Swelling from fluid accumulation.","volumes":[21]},{"term":"EEG","definition":"Electroencephalography, a scalp recording of summed electrical brain activity.","volumes":[25]},{"term":"Effusion","definition":"Fluid collection, such as around the lung (pleural effusion).","volumes":[21]},{"term":"Elastic recoil","definition":"The tendency of lung tissue to return to a smaller size after stretching.","volumes":[21]},{"term":"Elastin","definition":"A highly elastic dermal protein that allows skin to stretch and snap back into shape after mechanical deformation.","volumes":[16]},{"term":"Electrolytes","definition":"Minerals that carry electrical charge in body fluids — mainly sodium, plus potassium, magnesium, chloride. Lost in sweat; important in prolonged or hot exercise.","volumes":[14]},{"term":"Electromagnetic spectrum","definition":"The range of radiation classified by wavelength or frequency.","volumes":[26]},{"term":"Electromyography","definition":"A needle test recording electrical activity in muscle to assess nerve-muscle disorders.","volumes":[25]},{"term":"Elimination diet","definition":"A diet that removes suspected foods for a period; should only be done under professional supervision.","volumes":[9]},{"term":"Embolism","definition":"A blockage, such as a clot, in a blood vessel.","volumes":[21]},{"term":"Emergency action plan","definition":"A written plan from an individual's clinician describing their allergens, symptoms to watch for, which medication to give and when to call emergency services.","volumes":[9]},{"term":"Emergency department","definition":"A hospital service for urgent and life-threatening problems, with local variation in access.","volumes":[25]},{"term":"Emergency plan","definition":"A personal plan listing safe contacts and crisis numbers for distress.","volumes":[13]},{"term":"Emergency services","definition":"Services such as ambulance, fire or police. Call your local emergency number when immediate danger exists.","volumes":[13]},{"term":"Emmetropia","definition":"An optical state in which an unaccommodated eye focuses distant light on the retina.","volumes":[26]},{"term":"Emollient","definition":"A lipid or oil-based agent that fills microscopic cracks and crevices between shedding corneocytes to soften and smooth rough skin.","volumes":[16]},{"term":"Emotion","definition":"A brief, organised response to a meaningful event involving physiology, thoughts, expression and action.","volumes":[13]},{"term":"Emotion labelling","definition":"Naming an emotion accurately, which can help people respond flexibly.","volumes":[13]},{"term":"Emotion-focused coping","definition":"Coping that manages emotional responses to stress.","volumes":[13]},{"term":"Emotional awareness","definition":"Noticing and identifying feelings as they arise.","volumes":[13]},{"term":"Emotional eating","definition":"Eating in response to feelings rather than hunger. Common and understandable.","volumes":[13]},{"term":"Emotional regulation","definition":"Influencing which emotions people have, when, and how they are experienced and expressed.","volumes":[13]},{"term":"Empathy","definition":"Understanding and sharing another person's perspective or feelings. Includes cognitive and emotional components.","volumes":[13]},{"term":"Emphysema","definition":"Destruction of alveolar walls reducing gas-exchange area and recoil.","volumes":[21]},{"term":"Encephalitis","definition":"Inflammation of brain tissue, often causing altered consciousness, seizures or focal signs.","volumes":[25]},{"term":"Endocrine","definition":"Relating to hormones; some influence breathing indirectly.","volumes":[21]},{"term":"Energy systems","definition":"The three pathways that regenerate ATP: phosphagen (seconds), anaerobic glycolysis (~10 s–2 min), and aerobic oxidation (minutes+). They always overlap.","volumes":[14]},{"term":"Enteric nervous system","definition":"A network of neurons in the gut wall coordinating digestive activity.","volumes":[13]},{"term":"Enteric nervous system","definition":"The extensive neural network in the gut wall that controls local motility and secretion.","volumes":[25]},{"term":"Environment","definition":"Surroundings — air, home, work — that affect respiratory health.","volumes":[21]},{"term":"Enzyme","definition":"A protein that speeds a chemical reaction, such as carbonic anhydrase.","volumes":[21]},{"term":"Eosinophil","definition":"An immune cell involved in allergic responses.","volumes":[21]},{"term":"Eosinophilic oesophagitis (EoE)","definition":"A chronic immune-mediated condition of the oesophagus often linked with food triggers. Assessed and managed by specialists.","volumes":[9]},{"term":"EPA","definition":"Eicosapentaenoic acid, a long-chain omega-3 fatty acid with signalling roles.","volumes":[25]},{"term":"Epidemiology","definition":"The study of how diseases spread and affect populations.","volumes":[21]},{"term":"Epidermis","definition":"The outermost protective layer of the skin, composed predominantly of keratinocytes that continually divide, differentiate, and shed.","volumes":[16]},{"term":"Epiglottis","definition":"A flap that covers the larynx during swallowing to protect the airway.","volumes":[21]},{"term":"Epilepsy","definition":"A condition associated with recurrent unprovoked seizures or a high long-term risk of them.","volumes":[25]},{"term":"Epinephrine","definition":"See Adrenaline.","volumes":[13]},{"term":"Epinephrine (adrenaline)","definition":"The first-line emergency medicine for anaphylaxis, available as auto-injectors by prescription in many countries.","volumes":[9]},{"term":"Episodic","definition":"Occurring in episodes, as asthma symptoms often do.","volumes":[21]},{"term":"Epistaxis","definition":"Nosebleed.","volumes":[21]},{"term":"Eponychium (Cuticle)","definition":"The delicate protective seal of stratum corneum between the proximal nail fold and the nail plate.","volumes":[16]},{"term":"Ergonomics","definition":"Designing tasks and spaces to fit the person — e.g. desk and chair setup to support varied, comfortable posture.","volumes":[14]},{"term":"Erythema","definition":"Superficial reddening or violet discoloration of the skin caused by dilatation of dermal blood capillaries in response to injury or irritation.","volumes":[16]},{"term":"Erythrocyte","definition":"A red blood cell carrying haemoglobin.","volumes":[21]},{"term":"Essential Fatty Acids (EFAs)","definition":"Polyunsaturated lipids (linoleic acid, alpha-linolenic acid) that the human body cannot synthesize and must obtain via diet.","volumes":[16]},{"term":"Essential oil","definition":"A concentrated, volatile, aromatic liquid extracted from plant material, usually by distillation. Not a cooking ingredient in the ordinary sense and not for swallowing.","volumes":[3]},{"term":"Essential Oils","definition":"Concentrated volatile plant hydrophobic liquids containing complex mixtures of terpenes and phenols (e.g., linalool, limonene, eugenol).","volumes":[16]},{"term":"Essential tremor","definition":"A common movement disorder involving rhythmic tremor, especially of the hands.","volumes":[25]},{"term":"Etiology","definition":"The cause or origin of a disease.","volumes":[21]},{"term":"Eumelanin","definition":"A dark brown to black pigment that provides high photoprotective capacity against ultraviolet radiation and oxidative DNA damage.","volumes":[16]},{"term":"Eustachian tube","definition":"A passage linking the throat to the middle ear.","volumes":[21]},{"term":"Eustachian tube","definition":"A tube connecting the middle ear to the back of the nose. It helps equalise middle-ear pressure and drain fluid.","volumes":[28]},{"term":"Evaporation","definition":"The conversion of liquid to vapour, including the loss of water from the tear film.","volumes":[26]},{"term":"Evidence hierarchy","definition":"The general principle that different study designs provide different strengths of causal evidence.","volumes":[25]},{"term":"Exacerbation","definition":"A sudden worsening of chronic disease symptoms.","volumes":[21]},{"term":"Executive function","definition":"Mental processes for planning, working memory, inhibition and flexible behaviour.","volumes":[25]},{"term":"Exercise","definition":"Planned, structured, repetitive physical activity done to improve or maintain fitness or health — a subset of physical activity.","volumes":[14]},{"term":"Exercise intensity","definition":"How hard an activity is relative to a person's capacity — light, moderate or vigorous — measurable by the talk test, RPE or heart rate.","volumes":[14]},{"term":"Exercise physiology","definition":"The scientific study of how the body responds and adapts to exercise.","volumes":[14]},{"term":"Exercise tolerance","definition":"How much activity a person can do without undue symptoms.","volumes":[21]},{"term":"Exercise-associated hyponatremia","definition":"Dangerously low blood sodium from drinking far more plain fluid than sweat losses, sometimes during long endurance events. Prevent by drinking to thirst.","volumes":[14]},{"term":"Exhalation","definition":"Breathing out; usually passive recoil at rest.","volumes":[21]},{"term":"Exogen Phase","definition":"The active release phase where the old hair shaft is physically released and sheds from the follicular canal.","volumes":[16]},{"term":"Exogenous Ochronosis","definition":"A rare, difficult-to-treat dermatological condition causing blue-black hyperpigmentation following prolonged, unsupervised use of high-strength hydroquinone.","volumes":[16]},{"term":"Expectorant","definition":"A medicine intended to help clear mucus; evidence is limited.","volumes":[21]},{"term":"Exposure","definition":"Gradual, planned contact with feared situations, used in some clinical therapies under professional guidance.","volumes":[13]},{"term":"Exposure","definition":"Contact with a substance such as smoke, dust or pollen.","volumes":[21]},{"term":"Expressive writing","definition":"Writing about emotional experiences, a method studied in research with mixed results.","volumes":[13]},{"term":"External respiration","definition":"Gas exchange between alveoli and pulmonary capillaries.","volumes":[21]},{"term":"Extract (flavour)","definition":"A solution of flavour compounds, such as vanilla extract, made by soaking plant material in a solvent such as alcohol.","volumes":[3]},{"term":"Extrinsic Aging","definition":"Accelerated aging caused by external environmental factors including ultraviolet radiation, air pollution, smoking, and poor sleep.","volumes":[16]},{"term":"Eyelid","definition":"A movable tissue covering that protects the eye and helps distribute tears.","volumes":[26]},{"term":"Family history","definition":"Illnesses among relatives that may indicate inherited risk.","volumes":[21]},{"term":"Fartlek","definition":"A training method mixing continuous and interval work by feel — e.g. “speed play” with spontaneous surges. Less structured than formal intervals.","volumes":[14]},{"term":"Fascia","definition":"Connective tissue that wraps muscles, organs and body regions, transmitting force and contributing to elastic energy storage.","volumes":[14]},{"term":"FAST","definition":"Face, Arm, Speech, Time: a public stroke-recognition prompt to call emergency services.","volumes":[25]},{"term":"Fast-twitch (type II) fibres","definition":"Muscle fibres that produce high force quickly but fatigue sooner; subtypes IIa and IIx. Used in powerful, short efforts.","volumes":[14]},{"term":"Fatigue","definition":"Tiredness; common in many respiratory conditions.","volumes":[21]},{"term":"Febrile","definition":"Having a fever.","volumes":[21]},{"term":"FEV1","definition":"Forced expiratory volume in one second; reduced in obstruction.","volumes":[21]},{"term":"Fibrin","definition":"A protein involved in clot formation.","volumes":[21]},{"term":"Fibroblast","definition":"The primary cell of the dermis responsible for synthesizing collagen, elastin, and structural glycosaminoglycans.","volumes":[16]},{"term":"Fibrosis","definition":"Scarring of tissue, as in pulmonary fibrosis.","volumes":[21]},{"term":"Field of view","definition":"The area visible at a particular moment, depending on the observer and conditions.","volumes":[26]},{"term":"Fight, flight, freeze","definition":"Common defensive responses to threat.","volumes":[13]},{"term":"Filaggrin","definition":"A key filament-aggregating structural protein in the stratum corneum that binds keratin and later breaks down into natural moisturizing factors.","volumes":[16]},{"term":"Finasteride","definition":"A Type II 5-alpha reductase inhibitor medication that blocks the conversion of testosterone to dihydrotestosterone (DHT).","volumes":[16]},{"term":"Fissure","definition":"A groove dividing lung lobes.","volumes":[21]},{"term":"FITT principle","definition":"A planning framework: Frequency, Intensity, Time (duration), Type of exercise.","volumes":[14]},{"term":"Fitzpatrick Skin Phototypes","definition":"A numerical classification scale (Type I to Type VI) based on skin response to UV radiation regarding burning and tanning tendencies.","volumes":[16]},{"term":"Fixation","definition":"Directing the eyes towards a visual target.","volumes":[26]},{"term":"Flare-up","definition":"A sudden increase in symptoms of a chronic condition.","volumes":[21]},{"term":"Flashes","definition":"Brief perceived lights that can have several causes and may require urgent assessment when new.","volumes":[26]},{"term":"Flexibility","definition":"The range of motion available at a joint, influenced by muscle, connective tissue, joint structure and nervous control.","volumes":[14]},{"term":"Floaters","definition":"Moving spots or shapes perceived in vision, often related to shadows within the vitreous.","volumes":[26]},{"term":"Fluorescein","definition":"A dye used in certain eye examinations to make surface or vascular features easier to assess.","volumes":[26]},{"term":"Focal length","definition":"A measure of the distance over which an optical system brings light to focus.","volumes":[26]},{"term":"Focused attention","definition":"A meditation style keeping attention on a single object such as the breath.","volumes":[13]},{"term":"Folate","definition":"A B vitamin needed for DNA synthesis and early neural tube development.","volumes":[25]},{"term":"Folliculitis","definition":"Inflammation or superficial infection of one or more hair follicles, commonly presenting as itchy, tender small pustules.","volumes":[16]},{"term":"Food allergy","definition":"An immune-mediated adverse reaction to a food protein that occurs reproducibly on exposure.","volumes":[9]},{"term":"Food challenge","definition":"A clinician-supervised test where a person eats gradually increasing amounts of a food under medical observation. Must never be done at home.","volumes":[9]},{"term":"Food insecurity","definition":"Limited or uncertain access to adequate food due to money or other constraints.","volumes":[13]},{"term":"Food intolerance","definition":"A non-immune adverse reaction to a food, such as lactose intolerance.","volumes":[9]},{"term":"Food poisoning","definition":"Illness caused by harmful microbes, toxins or chemicals in food. Not an immune reaction to food proteins.","volumes":[9]},{"term":"Forced vital capacity (FVC)","definition":"The total air exhaled forcefully after a full breath in.","volumes":[21]},{"term":"Fortification","definition":"Adding nutrients to foods to prevent deficiency at population level.","volumes":[25]},{"term":"Fovea","definition":"A small central region of the macula specialised for fine-detail vision.","volumes":[26]},{"term":"FPIES","definition":"Food protein-induced enterocolitis syndrome: a non-IgE food allergy that typically causes repeated vomiting hours after eating the trigger food.","volumes":[9]},{"term":"Fragrance (Parfum)","definition":"A proprietary blend of natural or synthetic scent compounds; one of the leading causes of cosmetic allergic contact dermatitis.","volumes":[16]},{"term":"Fremitus","definition":"Vibration felt through the chest during speaking.","volumes":[21]},{"term":"Frontal lobe","definition":"The anterior cerebral lobe involved in movement, language production, planning and behaviour.","volumes":[25]},{"term":"Function","definition":"The normal activity of a body part.","volumes":[21]},{"term":"Functional fitness","definition":"The capacity to perform daily-life movements — standing, carrying, stairs, reaching — safely and confidently.","volumes":[14]},{"term":"Functional MRI","definition":"An imaging method measuring indirect blood-oxygenation changes associated with brain activity.","volumes":[25]},{"term":"Functional neurological disorder","definition":"A condition of genuine neurological symptoms arising from altered brain network functioning.","volumes":[25]},{"term":"Fundus examination","definition":"Clinical assessment of the inside back surface of the eye.","volumes":[26]},{"term":"Fundus photography","definition":"Photographic imaging of the back of the eye.","volumes":[26]},{"term":"Fungi","definition":"Organisms including moulds that can affect airways, especially when damp.","volumes":[21]},{"term":"GABA","definition":"The main fast inhibitory neurotransmitter in the adult central nervous system.","volumes":[25]},{"term":"Gait cycle","definition":"One complete cycle of a walking or running step — stance and swing phases (plus flight in running).","volumes":[14]},{"term":"Ganglion","definition":"A cluster of neuronal cell bodies outside the central nervous system.","volumes":[25]},{"term":"Ganglion cell","definition":"A retinal nerve cell whose fibre contributes to the optic nerve.","volumes":[26]},{"term":"Gas exchange","definition":"The transfer of oxygen and carbon dioxide between air and blood.","volumes":[21]},{"term":"Genetic counselling","definition":"Specialist support for understanding genetic information and its implications.","volumes":[25]},{"term":"Genetic variant","definition":"A DNA sequence difference that may be harmless, relevant to risk or uncertain in meaning.","volumes":[25]},{"term":"Genetics","definition":"Inherited traits that influence lung development and disease risk.","volumes":[21]},{"term":"Genetics","definition":"The study of inherited biological information and variation.","volumes":[26]},{"term":"Gentle movement","definition":"Low-intensity activity such as stretching, walking or tai chi.","volumes":[13]},{"term":"Genus","definition":"The first word of a botanical name, grouping closely related species, for example Cinnamomum.","volumes":[3]},{"term":"Geographic atrophy","definition":"An advanced form of dry AMD involving areas of retinal tissue loss.","volumes":[26]},{"term":"Glottis","definition":"The opening between the vocal cords.","volumes":[21]},{"term":"Glutamate","definition":"The main fast excitatory neurotransmitter in the mammalian central nervous system.","volumes":[25]},{"term":"Gluten","definition":"A family of proteins found in wheat, rye, barley and related grains.","volumes":[9]},{"term":"Gluten-free (labelling)","definition":"A claim governed by national rules. Thresholds include 20 mg/kg in Codex, the US, EU and UK, and \"no detectable gluten\" in Australia and New Zealand.","volumes":[9]},{"term":"Glycerin (Glycerol)","definition":"A classic, highly biocompatible trihydroxy alcohol that attracts water, stabilizes barrier lipids, and facilitates desquamation enzymes.","volumes":[16]},{"term":"Glycogen","definition":"The stored form of carbohydrate in muscle and liver; the main high-intensity fuel during exercise.","volumes":[14]},{"term":"Glycolysis","definition":"The anaerobic breakdown of glucose to ATP, producing lactate; dominant in hard efforts of roughly 10 seconds to 2 minutes.","volumes":[14]},{"term":"Golgi tendon organ","definition":"A sensory receptor in tendons that detects tension and helps protect muscle-tendon units from excessive force.","volumes":[14]},{"term":"Golgi tendon organ","definition":"A receptor at the muscle-tendon junction that detects force.","volumes":[25]},{"term":"Gonioscopy","definition":"A clinical examination of the drainage angle using a special lens.","volumes":[26]},{"term":"Granulocyte","definition":"An immune cell type involved in inflammation.","volumes":[21]},{"term":"Gratitude practice","definition":"Noticing and recording things one appreciates. Evidence is mixed but promising in some studies.","volumes":[13]},{"term":"Grey matter","definition":"Nervous tissue containing a high density of neuronal cell bodies and synapses.","volumes":[25]},{"term":"Grief","definition":"The natural response to loss. Its expression varies widely across cultures.","volumes":[13]},{"term":"Guillain-Barre syndrome","definition":"An immune-mediated polyneuropathy that can cause progressive weakness.","volumes":[25]},{"term":"Gut-brain axis","definition":"Bidirectional communication between gut and brain via nerves, hormones, immune and microbial signals.","volumes":[13]},{"term":"Haemoglobin","definition":"The iron-rich protein in red cells that carries most oxygen.","volumes":[21]},{"term":"Haemorrhagic stroke","definition":"Stroke caused by bleeding from a ruptured blood vessel in or around the brain.","volumes":[25]},{"term":"Hair cell","definition":"A sensory cell in the cochlea or vestibular organs that detects mechanical movement.","volumes":[25]},{"term":"Hair Cortex","definition":"The thick intermediate layer of the hair shaft comprising bundles of keratin intermediate filaments; determines hair strength, color, and elasticity.","volumes":[16]},{"term":"Hair Cuticle","definition":"The outermost protective layer of the hair shaft composed of overlapping, shingle-like transparent keratin scales.","volumes":[16]},{"term":"Hair Follicle","definition":"A dynamic mammalian mini-organ in the dermis that produces, anchors, and cycles hair through complex neuro-endothelial interactions.","volumes":[16]},{"term":"Hair Medulla","definition":"The central, often discontinuous or absent core of large, coarse hair fibers composed of loosely organized cells and air spaces.","volumes":[16]},{"term":"Hair Porosity","definition":"A measure of how readily the hair shaft absorbs and releases water, dictated by the alignment or lifting of cuticle scales.","volumes":[16]},{"term":"Halal","definition":"Permitted under Islamic dietary teaching. Certification schemes vary and do not address allergens.","volumes":[9]},{"term":"Hard Water","definition":"Water containing elevated concentrations of dissolved mineral ions, particularly calcium (Ca²⁺) and magnesium (Mg²⁺).","volumes":[16]},{"term":"Health equity","definition":"Fair opportunity for everyone to attain their best health.","volumes":[21]},{"term":"Hearing aid","definition":"A device worn in or behind the ear that amplifies and processes sound. It does not restore normal hearing or cure hearing loss.","volumes":[28]},{"term":"Hearing level (dB HL)","definition":"A decibel scale used on audiograms to compare hearing thresholds with reference values. It is not the same as environmental sound level.","volumes":[28]},{"term":"Hearing loop","definition":"An assistive listening system that transmits sound wirelessly to a telecoil-enabled hearing aid or receiver.","volumes":[28]},{"term":"Heart","definition":"The organ pumping blood through lungs and body.","volumes":[21]},{"term":"Heart rate (HR)","definition":"Beats per minute. Rises with exercise intensity; resting values vary widely between individuals.","volumes":[14]},{"term":"Heart rate variability","definition":"Variation in the interval between heartbeats, influenced by autonomic and other factors.","volumes":[25]},{"term":"Heart rate variability (HRV)","definition":"Variation in time between heartbeats, linked to autonomic regulation. Research use is complex; not a stress score.","volumes":[13]},{"term":"Heart-rate reserve (HRR)","definition":"Maximal heart rate minus resting heart rate — used in some individualised heart-rate zone methods.","volumes":[14]},{"term":"Heat acclimatisation","definition":"The body's adaptation to training in heat over roughly 1–2 weeks — lower heart rate and core temperature, earlier sweating — which improves heat tolerance.","volumes":[14]},{"term":"Herb","definition":"In cooking, usually the leafy green parts of non-woody plants used for flavour. Botanically the word has several meanings.","volumes":[3]},{"term":"Herbal product","definition":"A product made from plants. Can interact with medicines and is regulated differently by country.","volumes":[13]},{"term":"Hertz (Hz)","definition":"The unit of frequency, meaning one cycle per second. Human hearing is often described from around 20 Hz to 20,000 Hz, though sensitivity varies.","volumes":[28]},{"term":"Hidden allergen","definition":"An allergen that is present in a food in a way people do not expect — in a sauce, flavouring or processed ingredient — or under an unfamiliar name.","volumes":[9]},{"term":"HIIT (high-intensity interval training)","definition":"Alternating short vigorous efforts with recovery periods. Time-efficient and evidence-supported for some outcomes; optional, not required.","volumes":[14]},{"term":"Hippocampus","definition":"A brain structure important for memory and context, sensitive to some effects of stress.","volumes":[13]},{"term":"Hippocampus","definition":"A medial temporal structure critical for forming and retrieving certain episodic memories.","volumes":[25]},{"term":"Histamine","definition":"A chemical released by mast cells that widens blood vessels, causes itching and swelling, and tightens airways.","volumes":[9]},{"term":"Histamine","definition":"A chemical released in allergic reactions causing swelling and itching.","volumes":[21]},{"term":"Homeostasis","definition":"The body's maintenance of stable internal conditions.","volumes":[21]},{"term":"Homeostasis","definition":"Active regulation of internal conditions within ranges compatible with health.","volumes":[25]},{"term":"Homunculus","definition":"A distorted map of the body represented in sensory or motor cortex.","volumes":[25]},{"term":"Hormone","definition":"A chemical messenger carried in the blood.","volumes":[21]},{"term":"HPA axis","definition":"Hypothalamic-pituitary-adrenal axis. A hormonal system linking brain and adrenal glands to regulate stress hormones.","volumes":[13]},{"term":"HPA axis","definition":"The hypothalamic-pituitary-adrenal system regulating cortisol and stress adaptation.","volumes":[25]},{"term":"Humectant","definition":"A hygroscopic substance with chemical structures that attract and hold water molecules from the dermis and ambient air.","volumes":[16]},{"term":"Humidification","definition":"Adding moisture to inhaled air in the upper airways.","volumes":[21]},{"term":"Hyaluronic Acid","definition":"A naturally occurring glycosaminoglycan capable of binding up to 1,000 times its molecular weight in water.","volumes":[16]},{"term":"Hybrid","definition":"A plant that results from crossing two species or varieties. Marked with × in botanical names, as in Mentha × piperita.","volumes":[3]},{"term":"Hydration","definition":"Maintaining adequate fluid intake, which varies with climate, activity and health.","volumes":[13]},{"term":"Hydrocephalus","definition":"Abnormal accumulation of cerebrospinal fluid that can increase pressure.","volumes":[25]},{"term":"Hydrogen Bond (Hair)","definition":"Weak, temporary physical bonds between adjacent keratin chains easily broken by water and reset by heat drying.","volumes":[16]},{"term":"Hydroquinone","definition":"A potent tyrosinase inhibitor used medically for stubborn melasma and hyperpigmentation; restricted or prescription-only in many jurisdictions due to ochronosis risk.","volumes":[16]},{"term":"Hyperacusis","definition":"A reduced tolerance for everyday sounds that most people find comfortable. It is different from tinnitus and needs individual assessment.","volumes":[28]},{"term":"Hyperarousal","definition":"A state of heightened alertness that can interfere with rest and concentration.","volumes":[13]},{"term":"Hypercapnia","definition":"Abnormally high blood carbon dioxide.","volumes":[21]},{"term":"Hyperemia","definition":"Increased blood flow to a tissue.","volumes":[21]},{"term":"Hyperglycaemia","definition":"A higher-than-usual level of glucose in the blood.","volumes":[26]},{"term":"Hyperinflation","definition":"Abnormally increased lung volume from air trapping.","volumes":[21]},{"term":"Hyperkeratosis","definition":"Thickening of the stratum corneum often associated with increased keratin production in response to repetitive mechanical friction or disease.","volumes":[16]},{"term":"Hypermobility","definition":"Joints moving beyond the typical range; may require more strength and control rather than more stretching.","volumes":[14]},{"term":"Hyperpigmentation","definition":"A common, usually harmless condition where patches of skin become darker in color than the surrounding normal skin due to excess melanin deposition.","volumes":[16]},{"term":"Hyperresponsiveness","definition":"Excessive airway narrowing to stimuli.","volumes":[21]},{"term":"Hypersensitivity","definition":"An exaggerated immune reaction to a stimulus.","volumes":[21]},{"term":"Hypertrophy","definition":"An increase in muscle size from sustained progressive resistance training and adequate recovery and nutrition.","volumes":[14]},{"term":"Hypertrophy","definition":"Enlargement of tissue, such as respiratory muscles with training.","volumes":[21]},{"term":"Hyperventilation","definition":"Over-breathing that lowers CO2 and can cause symptoms.","volumes":[21]},{"term":"Hypocapnia","definition":"Abnormally low blood carbon dioxide.","volumes":[21]},{"term":"Hypodermis","definition":"Also called the subcutaneous tissue, the deepest layer composed primarily of adipose cells that provides mechanical cushioning and thermal insulation.","volumes":[16]},{"term":"Hypoglycaemia","definition":"Abnormally low blood glucose, which can disturb brain and autonomic function.","volumes":[25]},{"term":"Hyponychium","definition":"The thickened layer of stratum corneum underneath the free distal edge of the nail plate, sealing the nail bed from microbial entry.","volumes":[16]},{"term":"Hypopigmentation","definition":"A reduction in normal skin color resulting from diminished melanin synthesis, often following inflammation (pityriasis alba) or burns.","volumes":[16]},{"term":"Hypothalamus","definition":"A brain region coordinating hormonal and autonomic responses.","volumes":[13]},{"term":"Hypothalamus","definition":"A small region that regulates temperature, hunger, thirst, sleep and endocrine function.","volumes":[25]},{"term":"Hypoxia","definition":"Low oxygen in tissues.","volumes":[21]},{"term":"Idiopathic","definition":"Of unknown cause.","volumes":[21]},{"term":"IgE (immunoglobulin E)","definition":"An antibody type involved in immediate allergic reactions. Allergen-specific IgE attaches to mast cells and basophils.","volumes":[9]},{"term":"Ignition","definition":"The act of catching fire; relevant to combustion pollutants.","volumes":[21]},{"term":"Immune system","definition":"Cells and signals that defend the body against infection and injury.","volumes":[13]},{"term":"Immune system","definition":"The body's defence network against infection.","volumes":[21]},{"term":"Immune tolerance","definition":"The immune system's learned ability to ignore harmless substances such as food proteins.","volumes":[9]},{"term":"Immunity","definition":"Resistance to infection, natural or vaccine-induced.","volumes":[21]},{"term":"Immunoglobulin (Ig)","definition":"An antibody; IgE in allergies, IgA on mucosal surfaces.","volumes":[21]},{"term":"Immunosuppression","definition":"Reduced immune function increasing infection risk.","volumes":[21]},{"term":"Incentive spirometry","definition":"A device encouraging deep breaths after surgery.","volumes":[21]},{"term":"INCI (International Nomenclature of Cosmetic Ingredients)","definition":"A standardized international naming convention mandated on product packaging to identify cosmetic ingredients unambiguously.","volumes":[16]},{"term":"Incidence","definition":"The number or rate of new cases arising in a defined population over a period.","volumes":[26]},{"term":"Infection","definition":"Invasion and multiplication of a pathogen in the body.","volumes":[21]},{"term":"Infection","definition":"Invasion and multiplication of microorganisms in the body.","volumes":[26]},{"term":"Inflammation","definition":"A regulated immune response to injury or infection. Chronic inflammation is complex.","volumes":[13]},{"term":"Inflammation","definition":"The immune response to injury or threat; protective but harmful if chronic.","volumes":[21]},{"term":"Inflammation","definition":"A biological response to injury, infection or other triggers.","volumes":[26]},{"term":"Influenza","definition":"A viral respiratory illness, typically more severe than a cold.","volumes":[21]},{"term":"Infusion","definition":"A liquid made by steeping plant material in hot or cold water without extended simmering.","volumes":[3]},{"term":"Inhalation","definition":"Breathing in; also a medicine delivered to the airways.","volumes":[21]},{"term":"Inhaled corticosteroid","definition":"An anti-inflammatory preventer medicine for the airways.","volumes":[21]},{"term":"Insomnia","definition":"Persistent difficulty falling or staying asleep with daytime effects. Requires assessment if persistent.","volumes":[13]},{"term":"Insomnia","definition":"Persistent difficulty initiating or maintaining sleep with daytime consequences.","volumes":[25]},{"term":"Insula","definition":"A cortical region hidden within the lateral sulcus that contributes to taste, interoception and emotion.","volumes":[25]},{"term":"Intercostal muscles","definition":"Muscles between the ribs that assist breathing.","volumes":[21]},{"term":"Interoception","definition":"Awareness of internal bodily signals such as heartbeat and breathing.","volumes":[13]},{"term":"Interstitium","definition":"Tissue supporting the alveoli; affected in interstitial lung disease.","volumes":[21]},{"term":"Intraocular injection","definition":"Delivery of medicine into the eye by a trained clinical professional.","volumes":[26]},{"term":"Intraocular lens","definition":"An artificial lens implanted inside the eye, commonly after cataract removal.","volumes":[26]},{"term":"Intraocular pressure","definition":"The fluid pressure inside the eye.","volumes":[26]},{"term":"Intrinsic Aging","definition":"The genetically programmed, chronological aging process of human tissues governed by cellular senescence, telomere shortening, and metabolic byproducts.","volumes":[16]},{"term":"Intubation","definition":"Placement of a tube into the airway to assist breathing.","volumes":[21]},{"term":"Iodine","definition":"A mineral needed for thyroid hormone production and brain development.","volumes":[25]},{"term":"Iris","definition":"The coloured tissue that controls the size of the pupil.","volumes":[26]},{"term":"Iron","definition":"A mineral needed for oxygen transport and multiple cellular processes.","volumes":[25]},{"term":"Irrigation","definition":"Flushing an area with a suitable fluid, such as clean water in a chemical eye emergency.","volumes":[26]},{"term":"Irritant","definition":"A substance that provokes airway inflammation or cough.","volumes":[21]},{"term":"Irritant Contact Dermatitis (ICD)","definition":"Non-immunological skin damage caused by direct toxic, physical, or chemical disruption of the stratum corneum barrier.","volumes":[16]},{"term":"Ischaemic stroke","definition":"Stroke resulting from reduced blood flow, commonly due to a clot.","volumes":[25]},{"term":"Isokinetic","definition":"Muscle action at constant speed, usually on specialised machines; less common in general training.","volumes":[14]},{"term":"Isolation","definition":"Objective lack of social contact. Distinct from loneliness, which is a subjective feeling.","volumes":[13]},{"term":"Isometric contraction","definition":"A muscle action producing force without changing length — e.g. holding a plank.","volumes":[14]},{"term":"Journaling","definition":"Writing to reflect, process or plan. Used in many contexts.","volumes":[13]},{"term":"Keloid","definition":"An exaggerated fibroproliferative scar that extends beyond the original boundaries of an incision or wound, rich in dense type I collagen.","volumes":[16]},{"term":"Keratinocyte","definition":"The primary cell type found in the epidermis, responsible for producing keratin and establishing physical and immunological barriers.","volumes":[16]},{"term":"Keratitis","definition":"Inflammation of the cornea, sometimes caused by infection.","volumes":[26]},{"term":"Ketoconazole","definition":"A broad-spectrum imidazole antifungal agent formulated in medicated shampoos (1% OTC, 2% prescription) for dandruff and seborrhoeic dermatitis.","volumes":[16]},{"term":"Ketones","definition":"Molecules produced from fat during prolonged low glucose availability and usable as fuel.","volumes":[25]},{"term":"Kinesiology","definition":"The study of human movement, integrating anatomy, physiology and biomechanics.","volumes":[14]},{"term":"Kinetic chain","definition":"The linked segments (joints and muscles) that work together in a movement — e.g. ankle–knee–hip–spine in a squat.","volumes":[14]},{"term":"Koilonychia","definition":"Spoon-shaped nails where the outer edges flare upward and the center is depressed, capable of holding a drop of water.","volumes":[16]},{"term":"Kosher","definition":"Food prepared in accordance with Jewish dietary law. \"Pareve\" means no meat or dairy but not allergen-free.","volumes":[9]},{"term":"L-Ascorbic Acid (Vitamin C)","definition":"The pure, biologically active form of Vitamin C, a potent antioxidant that neutralizes free radicals and acts as an essential cofactor for collagen synthesis.","volumes":[16]},{"term":"Labyrinthitis","definition":"Inflammation of the inner ear, often used for vertigo with hearing change or hearing loss. It is a clinical description rather than a self-diagnosis.","volumes":[28]},{"term":"Lacrimal gland","definition":"A gland that produces part of the watery component of tears.","volumes":[26]},{"term":"Lactase","definition":"The enzyme that digests lactose. Reduced lactase activity causes lactose intolerance.","volumes":[9]},{"term":"Lactate","definition":"A product of anaerobic glycolysis. Once blamed for fatigue and soreness; now understood as a usable fuel. Clears within hours — it does not cause next-day DOMS.","volumes":[14]},{"term":"Lactate threshold","definition":"The exercise intensity above which lactate accumulates faster than it is cleared; rises with aerobic training.","volumes":[14]},{"term":"Lactose","definition":"The main sugar in milk. Lactose-free dairy products still contain milk proteins.","volumes":[9]},{"term":"Lamiaceae","definition":"The mint family. Includes basil, mint, thyme, oregano, sage and rosemary. Often square stems and aromatic leaves.","volumes":[3]},{"term":"Langerhans Cell","definition":"A specialized dendritic antigen-presenting immune cell situated within the epidermis that captures foreign antigens.","volumes":[16]},{"term":"Larynx","definition":"The voice box; protects the airway during swallowing.","volumes":[21]},{"term":"Laser treatment","definition":"Use of controlled light energy for a specific clinical purpose.","volumes":[26]},{"term":"Latent","definition":"Present but inactive, as in latent TB infection.","volumes":[21]},{"term":"Lateral geniculate nucleus","definition":"A thalamic relay involved in transmitting visual information to the cortex.","volumes":[26]},{"term":"Lens coating","definition":"A surface treatment on a lens designed to change properties such as reflection.","volumes":[26]},{"term":"Leukonychia","definition":"White spots, bands, or discoloration on the nail plate, most commonly caused by minor micro-trauma to the matrix during growth.","volumes":[16]},{"term":"Ligament","definition":"Fibrous connective tissue connecting bone to bone, stabilising joints — e.g. the ACL in the knee.","volumes":[14]},{"term":"Light adaptation","definition":"Adjustment of visual sensitivity after moving into brighter conditions.","volumes":[26]},{"term":"Limbic system","definition":"A group of interconnected regions involved in emotion, memory, motivation and internal regulation.","volumes":[25]},{"term":"Lipid layer","definition":"The outer, oil-rich part of the tear film that helps slow evaporation.","volumes":[26]},{"term":"Lobe","definition":"A major division of a lung; right has three, left has two.","volumes":[21]},{"term":"Locomotion","definition":"Movement that transports the body through space — walking, running, cycling, swimming, wheeling.","volumes":[14]},{"term":"Loneliness","definition":"The distressing feeling of a gap between desired and actual social connection.","volumes":[13]},{"term":"Long-term potentiation","definition":"A sustained activity-dependent increase in synaptic strength, relevant to learning.","volumes":[25]},{"term":"Loving-kindness practice","definition":"A meditation cultivating warm wishes toward oneself and others.","volumes":[13]},{"term":"Low-vision aid","definition":"A tool that helps a person use their available vision for a particular activity.","volumes":[26]},{"term":"Lower motor neuron","definition":"A neuron with an axon that directly innervates skeletal muscle.","volumes":[25]},{"term":"Lower respiratory tract","definition":"Airways below the vocal cords: trachea, bronchi, lungs.","volumes":[21]},{"term":"Lubricant eye drop","definition":"A sterile preparation intended to add lubrication to the ocular surface.","volumes":[26]},{"term":"Lumbar puncture","definition":"A procedure that samples cerebrospinal fluid with a needle in the lower back.","volumes":[25]},{"term":"Lung","definition":"The organ of gas exchange; two in the chest.","volumes":[21]},{"term":"Lung capacity","definition":"The total volume of air the lungs can hold.","volumes":[21]},{"term":"Lung compliance","definition":"How easily the lungs stretch as pressure is applied.","volumes":[21]},{"term":"Lung volume","definition":"The amount of air moved in a given breathing state.","volumes":[21]},{"term":"Lunula","definition":"The pale, crescent-shaped white region visible at the base of the nail plate, representing the distal edge of the nail matrix.","volumes":[16]},{"term":"Lupin","definition":"A legume used as flour in some baked goods and pasta; a declared allergen in the EU, UK and Australia/New Zealand.","volumes":[9]},{"term":"Lymph node","definition":"Tissue that filters lymph and houses immune cells.","volumes":[21]},{"term":"Lymphocyte","definition":"A white cell central to adaptive immunity.","volumes":[21]},{"term":"Macronutrient","definition":"A nutrient required in large amounts, such as carbohydrate, protein or fat.","volumes":[25]},{"term":"Macrophage","definition":"An immune cell that engulfs microbes and debris in the lungs.","volumes":[21]},{"term":"Macular oedema","definition":"Swelling of the macula caused by fluid accumulation.","volumes":[26]},{"term":"Magnification","definition":"An increase in the apparent size of an image or object.","volumes":[26]},{"term":"Maillard reaction","definition":"A group of browning reactions between amino acids and sugars at higher temperatures that create roasted flavours.","volumes":[3]},{"term":"Malaise","definition":"A general feeling of being unwell.","volumes":[21]},{"term":"Malassezia","definition":"A genus of lipid-dependent commensal yeasts naturally residing on human skin and scalp.","volumes":[16]},{"term":"Masking","definition":"Concealing natural responses to appear more neurotypical, which can be costly to wellbeing.","volumes":[25]},{"term":"Mast cell","definition":"An immune cell in tissues such as skin, airways and gut that releases histamine and other mediators in allergic reactions.","volumes":[9]},{"term":"Mast cell","definition":"An immune cell releasing histamine in allergic responses.","volumes":[21]},{"term":"Mastoiditis","definition":"Inflammation or infection of the air-filled bone behind the ear, often as a complication of middle-ear infection. Swelling, redness or severe pain behind the ear is urgent.","volumes":[28]},{"term":"May contain","definition":"A common precautionary allergen label indicating the possibility of unintended allergen presence. Usually voluntary, with varying meaning.","volumes":[9]},{"term":"Mechanoreceptor","definition":"A sensor detecting stretch in the lungs and airways.","volumes":[21]},{"term":"Meditation","definition":"Diverse contemplative practices training attention or awareness.","volumes":[13]},{"term":"Medulla oblongata","definition":"Brainstem region generating breathing rhythm.","volumes":[21]},{"term":"Medulla oblongata","definition":"The lower brainstem region containing key centres for breathing and circulation.","volumes":[25]},{"term":"Meibomian gland","definition":"An eyelid gland that produces oils contributing to the tear film.","volumes":[26]},{"term":"Melanocyte","definition":"A specialized dendritic cell located in the stratum basale that synthesizes the pigment melanin and transfers it to neighboring keratinocytes.","volumes":[16]},{"term":"Melanoma","definition":"A malignant neoplasm originating from melanocytes, representing the most lethal form of skin cancer.","volumes":[16]},{"term":"Melasma","definition":"A common acquired hyperpigmentary disorder causing symmetrical brown or gray-brown patches on sun-exposed facial areas.","volumes":[16]},{"term":"Melatonin","definition":"A hormone involved in signalling night-time to the body. Supplement use should be discussed with a clinician.","volumes":[13]},{"term":"Melatonin","definition":"A hormone from the pineal gland that participates in circadian timing.","volumes":[25]},{"term":"Meninges","definition":"The three membranes - dura, arachnoid and pia mater - that protect the brain and spinal cord.","volumes":[25]},{"term":"Meningitis","definition":"Inflammation of the meninges, often from infection.","volumes":[25]},{"term":"Mental-health condition","definition":"A clinically recognised pattern of symptoms requiring assessment.","volumes":[13]},{"term":"Mercury (in Cosmetics)","definition":"A toxic heavy metal illegally added to counterfeit or unregulated skin-lightening creams that causes kidney damage, neuropathy, and paradoxically darkens skin.","volumes":[16]},{"term":"Meridian","definition":"A direction through the optical system used to describe differences in refractive power.","volumes":[26]},{"term":"MET (metabolic equivalent)","definition":"A unit of energy cost: 1 MET is resting energy use. Moderate activity is roughly 3–6 METs; vigorous is above 6.","volumes":[14]},{"term":"MET-minute","definition":"Activity volume expressed as METs × minutes — a common way guidance expresses weekly targets.","volumes":[14]},{"term":"Meta-analysis","definition":"A statistical combination of results from several studies of the same question.","volumes":[3]},{"term":"Metabolism","definition":"The chemical processes that keep the body alive, needing oxygen.","volumes":[21]},{"term":"Metered-dose inhaler (MDI)","definition":"An inhaler releasing a measured dose; often used with a spacer.","volumes":[21]},{"term":"Micellar Water","definition":"A gentle cleansing liquid containing suspended surfactant micelles that attract dirt and oil without requiring vigorous mechanical scrubbing.","volumes":[16]},{"term":"Microbiome","definition":"The community of microorganisms in a body site.","volumes":[21]},{"term":"Microbiota","definition":"The community of microorganisms living in the body, especially the gut.","volumes":[13]},{"term":"Microcycle","definition":"A week of training within a larger programme — the usual planning unit.","volumes":[14]},{"term":"Microdermabrasion","definition":"A non-invasive cosmetic physical exfoliation technique using abrasive crystals or diamond-tipped wands to remove stratum corneum cells.","volumes":[16]},{"term":"Microneedling","definition":"A procedure utilizing tiny sterile needles to puncture the skin, creating micro-injuries that stimulate endogenous collagen and elastin synthesis.","volumes":[16]},{"term":"Micronutrient","definition":"A vitamin or mineral needed in small amounts.","volumes":[25]},{"term":"Micronutrient","definition":"A vitamin or mineral needed in relatively small amounts.","volumes":[26]},{"term":"Microorganism","definition":"A microscopic organism such as a bacterium, virus or fungus.","volumes":[21]},{"term":"Microsuction","definition":"Removal of earwax or debris using a suction instrument under magnification, usually performed by a trained clinician.","volumes":[28]},{"term":"Midbrain","definition":"The upper brainstem region involved in eye movement, movement control and arousal.","volumes":[25]},{"term":"Migraine","definition":"A neurological condition involving recurring attacks of headache and sensory or autonomic symptoms.","volumes":[25]},{"term":"Milia","definition":"Tiny, firm, benign pearly-white cysts trapped beneath the epidermis containing keratin, commonly found around eyes and cheeks.","volumes":[16]},{"term":"Mindfulness","definition":"Paying attention to present experience with openness and without automatic judgement.","volumes":[13]},{"term":"Minoxidil","definition":"An FDA/EMA approved topical and low-dose oral medication that shortens telogen, prolongs anagen, and increases hair follicle size.","volumes":[16]},{"term":"Mitochondria","definition":"The cell's aerobic energy factories; their number and efficiency increase with endurance training.","volumes":[14]},{"term":"Mitochondria","definition":"Cell structures that make energy using oxygen.","volumes":[21]},{"term":"Mixed hearing loss","definition":"Hearing loss with both conductive and sensorineural components.","volumes":[28]},{"term":"Mobility","definition":"Active, controlled range of motion at a joint — flexibility plus strength and neuromuscular control through that range.","volumes":[14]},{"term":"Molluscs","definition":"A group of shellfish including bivalves (oysters, mussels, clams, scallops), cephalopods (squid, octopus) and gastropods (snails, abalone).","volumes":[9]},{"term":"Monocular","definition":"Relating to one eye.","volumes":[26]},{"term":"Monofocal lens","definition":"A lens designed with one principal optical power.","volumes":[26]},{"term":"Morphology","definition":"The form and structure of an organism, such as leaf shape or flower arrangement.","volumes":[3]},{"term":"Motor cortex","definition":"The brain region planning and initiating voluntary movement.","volumes":[14]},{"term":"Motor cortex","definition":"Cortical regions that help plan, initiate and control voluntary movement.","volumes":[25]},{"term":"Motor neuron disease","definition":"A group of conditions involving degeneration of motor neurons.","volumes":[25]},{"term":"Motor unit","definition":"One motor neuron and all the muscle fibres it activates. Recruited small-to-large (size principle) as effort increases.","volumes":[14]},{"term":"MRI","definition":"Magnetic resonance imaging, a detailed structural imaging method using magnetic fields and radio waves.","volumes":[25]},{"term":"Mucin","definition":"A component associated with the wetting and stability of the ocular surface.","volumes":[26]},{"term":"Mucociliary escalator","definition":"Coordinated cilia movement clearing mucus upward.","volumes":[21]},{"term":"Mucolytics","definition":"Medicines that thin mucus; prescribed in some conditions.","volumes":[21]},{"term":"Mucosa","definition":"The moist lining of airways and other surfaces.","volumes":[21]},{"term":"Mucus","definition":"A sticky secretion trapping particles and microbes.","volumes":[21]},{"term":"Multidisciplinary team","definition":"A coordinated group of professionals with different expertise working with the person.","volumes":[25]},{"term":"Multiple sclerosis","definition":"An immune-mediated demyelinating condition of the central nervous system.","volumes":[25]},{"term":"Muscle fibre","definition":"A single muscle cell. Types I (slow, fatigue-resistant) and II (fast, powerful) differ in speed, force and endurance.","volumes":[14]},{"term":"Muscle protein synthesis (MPS)","definition":"The building of new muscle protein. Raised by resistance exercise and protein intake; must exceed breakdown over time for growth.","volumes":[14]},{"term":"Muscle spindle","definition":"A stretch-sensitive receptor within muscle that reports length and movement.","volumes":[25]},{"term":"Muscle tension","definition":"Sustained contraction of muscles, which can be increased by stress and posture.","volumes":[13]},{"term":"Muscular endurance","definition":"The ability of a muscle to sustain repeated contractions or a held contraction over time.","volumes":[14]},{"term":"Muscular strength","definition":"The maximum force a muscle or muscle group can produce in a single effort.","volumes":[14]},{"term":"Myasthenia gravis","definition":"An autoimmune neuromuscular junction disorder causing fatigable weakness.","volumes":[25]},{"term":"Myelin","definition":"A lipid-rich wrapping around many axons that speeds electrical conduction.","volumes":[25]},{"term":"Myelination","definition":"Formation of myelin sheaths around axons, improving conduction speed.","volumes":[25]},{"term":"Myenteric plexus","definition":"The enteric nerve network between gut muscle layers that mainly controls motility.","volumes":[25]},{"term":"Myofibril","definition":"The contractile strands inside a muscle fibre, made of repeating sarcomeres containing actin and myosin.","volumes":[14]},{"term":"Myopia management","definition":"Clinical strategies intended to slow progression of myopia in suitable individuals.","volumes":[26]},{"term":"Myosin","definition":"The thick contractile protein in sarcomeres; its heads bind actin to generate force.","volumes":[14]},{"term":"Ménière’s disease","definition":"A vestibular condition characterised by recurrent vertigo episodes with fluctuating hearing, ear fullness or tinnitus. Diagnosis is based on clinical criteria.","volumes":[28]},{"term":"Nail Bed","definition":"The vascular, richly innervated soft tissue beneath the nail plate that adheres to and supports the plate as it advances distally.","volumes":[16]},{"term":"Nail Matrix","definition":"The active germinative tissue located beneath the proximal nail fold that generates new nail plate cells.","volumes":[16]},{"term":"Nail Plate","definition":"The hard, visible, translucent outer structure of the nail made of dense, compact, flattened layers of hard alpha-keratin.","volumes":[16]},{"term":"Nasal cavity","definition":"The space inside the nose that conditions incoming air.","volumes":[21]},{"term":"Native range","definition":"The geographic area where a plant evolved or occurs naturally, as opposed to where it is grown today.","volumes":[3]},{"term":"Natural Moisturizing Factors (NMF)","definition":"A collection of water-soluble intracellular compounds inside corneocytes (amino acids, PCA, urea, lactate) that bind atmospheric and dermal water.","volumes":[16]},{"term":"Near addition","definition":"Extra lens power prescribed to assist near focus, often abbreviated as add.","volumes":[26]},{"term":"Nebulizer","definition":"A device turning liquid medicine into an inhalable mist.","volumes":[21]},{"term":"Negative feedback","definition":"A regulatory loop where an output reduces further activation, as cortisol does on the HPA axis.","volumes":[13]},{"term":"Negative feedback","definition":"A loop in which a response opposes the initial deviation and restores balance.","volumes":[25]},{"term":"Nerve","definition":"A fibre carrying signals, including those controlling breathing.","volumes":[21]},{"term":"Nerve conduction study","definition":"A test measuring the speed and strength of electrical conduction along peripheral nerves.","volumes":[25]},{"term":"Neural signal","definition":"An electrical or chemical message transmitted by nerve cells.","volumes":[26]},{"term":"Neuralgia","definition":"Pain along the course of a nerve due to irritation or damage.","volumes":[25]},{"term":"Neurodiversity","definition":"The idea that variation in neurological development and cognitive style is part of human diversity.","volumes":[25]},{"term":"Neurogenesis","definition":"The production of new neurons, well established during development and studied in specific adult regions.","volumes":[25]},{"term":"Neurological examination","definition":"A structured assessment of brain, spinal cord and nerve function.","volumes":[25]},{"term":"Neuromotor exercise","definition":"Training of balance, agility and coordination — recommended for all adults and especially older adults.","volumes":[14]},{"term":"Neuromuscular adaptation","definition":"Improvements in the nervous system's control of muscle — recruitment, firing rate, coordination — the main driver of early strength gains.","volumes":[14]},{"term":"Neuromuscular junction","definition":"The synapse where a motor neuron signals a muscle fibre to contract.","volumes":[14]},{"term":"Neuromuscular junction","definition":"The synapse between a motor neuron and a muscle fibre.","volumes":[25]},{"term":"Neuron","definition":"A specialised cell that receives, integrates and transmits information.","volumes":[25]},{"term":"Neuropathic pain","definition":"Pain caused by a lesion or disease of the somatosensory nervous system.","volumes":[25]},{"term":"Neuropathy","definition":"Disease or damage affecting peripheral nerves.","volumes":[25]},{"term":"Neuroplasticity","definition":"The brain's capacity to change in structure and function through experience. Not a quick fix; changes are gradual.","volumes":[13]},{"term":"Neuroplasticity","definition":"The nervous system's capacity to change its structure and function with experience.","volumes":[25]},{"term":"Neuroplasticity","definition":"The capacity of neural networks to change with experience or after injury.","volumes":[26]},{"term":"Neurotransmitter","definition":"A chemical messenger transmitting signals between neurons.","volumes":[13]},{"term":"Neurotransmitter","definition":"A chemical carrying signals between nerve cells.","volumes":[21]},{"term":"Neurotransmitter","definition":"A chemical released at a synapse that changes the activity of a target cell.","volumes":[25]},{"term":"Neurotypical","definition":"A term for neurological development or functioning that is broadly typical of the majority.","volumes":[25]},{"term":"Niacinamide (Vitamin B3)","definition":"A water-soluble physiological precursor to NAD/NADP that supports ceramide synthesis, calms redness, and moderates sebum.","volumes":[16]},{"term":"Nicotine","definition":"The addictive chemical in tobacco and many vapes.","volumes":[21]},{"term":"Nitric oxide","definition":"A gas made in the airways that mildly dilates them.","volumes":[21]},{"term":"Nitrogen dioxide (NO2)","definition":"A traffic-related air pollutant irritating the airways.","volumes":[21]},{"term":"Nociception","definition":"Encoding of stimuli that are or may become damaging to tissue.","volumes":[25]},{"term":"Nociceptive pain","definition":"Pain arising from actual or threatened damage to non-neural tissue and detected by nociceptors.","volumes":[25]},{"term":"Nocturnal","definition":"Occurring at night, as some asthma symptoms do.","volumes":[21]},{"term":"Node of Ranvier","definition":"A short unmyelinated gap in a myelinated axon where the action potential regenerates.","volumes":[25]},{"term":"Noise dose","definition":"An estimate of total noise exposure based on sound level and duration. Occupational dose concepts are population-level guides, not individual diagnoses.","volumes":[28]},{"term":"Noise-induced hearing loss","definition":"Hearing damage caused or contributed to by loud sound. It may occur gradually or after a single high-intensity event.","volumes":[28]},{"term":"Non-celiac gluten sensitivity","definition":"Symptoms attributed to gluten-containing foods in people with neither celiac disease nor wheat allergy. Mechanism is not fully understood.","volumes":[9]},{"term":"Non-IgE-mediated allergy","definition":"Food allergy involving immune pathways other than IgE, often with delayed symptoms.","volumes":[9]},{"term":"Non-invasive ventilation","definition":"Assisted breathing without a tube in the trachea.","volumes":[21]},{"term":"Noradrenaline","definition":"Also called norepinephrine. A neurotransmitter and hormone involved in arousal and attention.","volumes":[13]},{"term":"Norepinephrine","definition":"A catecholamine neurotransmitter used by many sympathetic pathways and brain networks.","volumes":[25]},{"term":"Nucleus","definition":"The control centre of a cell.","volumes":[21]},{"term":"Nutrition","definition":"Intake of nutrients through food; supports general health.","volumes":[13]},{"term":"Nystagmus","definition":"Involuntary rhythmic movement of the eyes.","volumes":[26]},{"term":"Nystagmus","definition":"Rhythmic, involuntary eye movement. It can be a normal response to head movement or a sign of vestibular or neurological dysfunction.","volumes":[28]},{"term":"Observational study","definition":"A study observing associations without randomly assigning an intervention.","volumes":[25]},{"term":"Obstructive","definition":"A pattern where airflow, especially exhalation, is limited.","volumes":[21]},{"term":"Occipital lobe","definition":"The posterior cerebral lobe mainly responsible for visual processing.","volumes":[25]},{"term":"Occlusion therapy","definition":"A treatment that covers one eye in selected cases, often for childhood amblyopia.","volumes":[26]},{"term":"Occlusive","definition":"A physical hydrophobic barrier ingredient that coats the skin surface to physically block trans-epidermal water loss.","volumes":[16]},{"term":"Occupational stress","definition":"Stress arising from work demands, control, relationships and rewards.","volumes":[13]},{"term":"Occupational therapy","definition":"Support for daily activities, thinking, equipment and environmental adaptation.","volumes":[25]},{"term":"OCT","definition":"The abbreviation for optical coherence tomography.","volumes":[26]},{"term":"Ocular","definition":"Relating to the eye.","volumes":[26]},{"term":"Ocular hypertension","definition":"Higher-than-usual intraocular pressure without necessarily establishing glaucoma.","volumes":[26]},{"term":"Oedema","definition":"Swelling from fluid, including pulmonary oedema.","volumes":[21]},{"term":"Oesophagus","definition":"The food pipe behind the trachea.","volumes":[21]},{"term":"Olfaction","definition":"The sense of smell, based in the nasal cavity.","volumes":[21]},{"term":"Olfactory bulb","definition":"The first central relay for olfactory signals.","volumes":[25]},{"term":"Olfactory epithelium","definition":"Nasal tissue containing receptor neurons that detect odour molecules.","volumes":[25]},{"term":"Omega-3 fatty acid","definition":"A family of essential fats important for membranes and signalling.","volumes":[25]},{"term":"Onycholysis","definition":"The painless separation of the nail plate from the underlying pink nail bed, typically starting at the distal or lateral margins.","volumes":[16]},{"term":"Onychomycosis","definition":"A fungal infection of the nail plate or nail bed, most often caused by dermatophytes (such as Trichophyton rubrum).","volumes":[16]},{"term":"Onychorrhexis","definition":"Longitudinal ridging and brittle splitting along the length of the nail plate, common in dry climates and chronological aging.","volumes":[16]},{"term":"Open kinetic chain","definition":"An exercise where the limb's end is free to move — e.g. a leg extension; useful for isolating muscles.","volumes":[14]},{"term":"Open monitoring","definition":"A meditation style observing whatever arises without focusing on one object.","volumes":[13]},{"term":"Ophthalmologist","definition":"A medical doctor specialising in eye disease and its medical or surgical care.","volumes":[26]},{"term":"Ophthalmoscope","definition":"An instrument used to examine structures inside the eye.","volumes":[26]},{"term":"Optic chiasm","definition":"The crossing point where some visual fibres pass to the opposite hemisphere.","volumes":[25]},{"term":"Optic disc","definition":"The point on the retina where optic nerve fibres leave the eye.","volumes":[26]},{"term":"Optic nerve","definition":"The nerve that carries visual signals from the retina toward the brain.","volumes":[25]},{"term":"Optic neuritis","definition":"Inflammation of the optic nerve that can affect visual function.","volumes":[26]},{"term":"Optical power","definition":"A measure of how strongly an optical element converges or diverges light.","volumes":[26]},{"term":"Optician","definition":"A professional involved in providing or fitting optical appliances; roles vary by jurisdiction.","volumes":[26]},{"term":"Optometrist","definition":"An eye-care professional who assesses vision and eye health; scope varies by jurisdiction.","volumes":[26]},{"term":"Optotype","definition":"A standardised symbol or letter used in a visual acuity chart.","volumes":[26]},{"term":"Oral allergy syndrome / pollen-food allergy syndrome","definition":"Mouth itching or tingling after raw fruits, vegetables or nuts in some people with pollen allergy, from cross-reactive proteins.","volumes":[9]},{"term":"Orthostatic hypotension","definition":"A fall in blood pressure on standing that can cause dizziness or fainting.","volumes":[25]},{"term":"Osmolality","definition":"The concentration of dissolved particles in a fluid, relevant to water balance and thirst.","volumes":[25]},{"term":"Ossicles","definition":"The three tiny middle-ear bones—the malleus, incus and stapes—that transmit eardrum vibration to the inner ear.","volumes":[28]},{"term":"Otitis externa","definition":"Inflammation or infection of the outer-ear canal, sometimes called swimmer’s ear. It is distinct from a middle-ear infection.","volumes":[28]},{"term":"Otitis media","definition":"Inflammation or infection of the middle ear, often associated with fluid. It can be acute or chronic.","volumes":[28]},{"term":"Otoacoustic emissions (OAEs)","definition":"Low-intensity sounds produced by functioning cochlear hair cells and measured with a small probe. OAEs are used in newborn screening and some diagnostic testing.","volumes":[28]},{"term":"Otolaryngologist (ENT)","definition":"A medical specialist in conditions of the ear, nose, throat, head and neck. Also called an otorhinolaryngologist.","volumes":[28]},{"term":"Otolith organ","definition":"A vestibular structure detecting linear acceleration and head tilt.","volumes":[25]},{"term":"Otolith organs","definition":"The utricle and saccule in the inner ear. They sense gravity and linear acceleration, helping the brain know head position and motion.","volumes":[28]},{"term":"Otosclerosis","definition":"Abnormal bone remodelling around the middle-ear structures, often causing progressive conductive hearing loss. It can run in families.","volumes":[28]},{"term":"Overreaching","definition":"A short-term performance dip from training load exceeding recovery; resolves with rest (functional) or persists if prolonged (non-functional).","volumes":[14]},{"term":"Overtraining","definition":"See overtraining syndrome.","volumes":[14]},{"term":"Overtraining syndrome","definition":"A prolonged state of fatigue and performance decline from sustained load–recovery imbalance, with physical, mood and sleep symptoms.","volumes":[14]},{"term":"Overuse injury","definition":"Tissue damage from repeated load exceeding recovery over time — e.g. tendinopathy, shin splints, stress reactions. Usually “too much too soon”.","volumes":[14]},{"term":"Oxidative Stress","definition":"An imbalance between production of reactive oxygen species (free radicals) and the endogenous antioxidant defenses of the body.","volumes":[16]},{"term":"Oxygen (O2)","definition":"The gas cells need to make energy; about 21% of air.","volumes":[21]},{"term":"Oxygen dissociation curve","definition":"A graph of haemoglobin saturation versus oxygen pressure.","volumes":[21]},{"term":"Oxygen saturation","definition":"The percentage of haemoglobin binding sites carrying oxygen.","volumes":[21]},{"term":"Oxygen therapy","definition":"Prescribed oxygen for low blood oxygen; medically supervised.","volumes":[21]},{"term":"Ozone (O3)","definition":"A reactive gas and smog component irritating airways.","volumes":[21]},{"term":"PA Rating System","definition":"A Japanese and East Asian photoprotection rating system based on Persistent Pigment Darkening (PPD) reflecting UVA defense (from PA+ to PA++++).","volumes":[16]},{"term":"Pachymetry","definition":"Measurement of corneal thickness.","volumes":[26]},{"term":"PAL (precautionary allergen labelling)","definition":"Voluntary statements such as \"may contain\" that warn of possible cross-contact in manufacturing.","volumes":[9]},{"term":"Pallor","definition":"Paleness, sometimes from poor circulation or illness.","volumes":[21]},{"term":"Palpation","definition":"Feeling the body, such as the chest, during examination.","volumes":[21]},{"term":"PAR-Q+","definition":"Physical Activity Readiness Questionnaire — a screening tool identifying people who should seek medical advice before becoming more active.","volumes":[14]},{"term":"Parabens","definition":"A class of widely evaluated preservatives (e.g., methylparaben, ethylparaben) preventing bacterial and mold growth in aqueous cosmetic formulations.","volumes":[16]},{"term":"Paranasal sinus","definition":"An air-filled skull cavity opening into the nose.","volumes":[21]},{"term":"Parasympathetic nervous system","definition":"The autonomic branch associated with rest, digestion and recovery.","volumes":[13]},{"term":"Parietal lobe","definition":"The cerebral lobe behind the central sulcus involved in touch, spatial processing and attention.","volumes":[25]},{"term":"Parkinson disease","definition":"A progressive neurological condition involving motor and non-motor symptoms.","volumes":[25]},{"term":"Parkinsonism","definition":"A clinical syndrome of slowness, rigidity and variable tremor with multiple possible causes.","volumes":[25]},{"term":"Paronychia","definition":"Inflammation and infection of the tissue folds surrounding the nail, characterized by acute redness, swelling, tenderness, and sometimes pus.","volumes":[16]},{"term":"Partial pressure","definition":"The pressure of one gas within a mixture; drives diffusion.","volumes":[21]},{"term":"Patch Testing","definition":"A standardized dermatological diagnostic method placing diluted suspected allergens on the back for 48 hours to identify Type IV hypersensitivities.","volumes":[16]},{"term":"Patching","definition":"Covering one eye as directed in selected forms of visual treatment.","volumes":[26]},{"term":"Pathogen","definition":"A microorganism that can cause disease.","volumes":[21]},{"term":"PEAL","definition":"Plain English Allergen Labelling: Australian and New Zealand requirements for naming allergens in a consistent way with a summary statement.","volumes":[9]},{"term":"Penetrance","definition":"The chance that carrying a particular genetic variant leads to observable features.","volumes":[25]},{"term":"Peptides","definition":"Short chains of amino acids that serve as biological messengers or copper-complexing agents to signal cellular matrix repair.","volumes":[16]},{"term":"Percussion","definition":"Tapping the chest to assess underlying tissue.","volumes":[21]},{"term":"Perforated eardrum","definition":"A hole or tear in the eardrum, often caused by infection, trauma or pressure change. Assessment is needed to exclude complications.","volumes":[28]},{"term":"Perfusion","definition":"Blood flow through the lung capillaries.","volumes":[21]},{"term":"Pericarp","definition":"The wall of a fruit. In pepper, the pericarp is the outer skin removed to make white pepper.","volumes":[3]},{"term":"Period After Opening (PAO) Symbol","definition":"An icon resembling an open jar with a number followed by \"M\" (e.g., 6M, 12M) indicating how many months the product remains safe after unsealing.","volumes":[16]},{"term":"Periodisation","definition":"Planned variation of training over weeks and months (cycles) to peak performance and manage fatigue.","volumes":[14]},{"term":"Peripheral nervous system","definition":"Nerves outside the brain and spinal cord.","volumes":[13]},{"term":"Peripheral neuropathy","definition":"Dysfunction or damage of nerves outside the brain and spinal cord.","volumes":[25]},{"term":"Peripheral vision","definition":"Vision outside the central area of gaze.","volumes":[26]},{"term":"Peristalsis","definition":"Coordinated waves of muscle contraction that move material through the gut.","volumes":[25]},{"term":"Perspective-taking","definition":"Considering a situation from another person's viewpoint.","volumes":[13]},{"term":"PET scan","definition":"Positron emission tomography, a nuclear imaging method measuring tracers related to metabolism or receptors.","volumes":[25]},{"term":"Petrolatum (Petroleum Jelly)","definition":"A purified semi-solid mixture of heavy hydrocarbons that acts as an inert, highly effective moisture sealant.","volumes":[16]},{"term":"pH (Skin Potential of Hydrogen)","definition":"A logarithmic measure of acidity or alkalinity on a scale of 0 to 14. Healthy skin surface pH averages 4.5 to 5.5 (mildly acidic).","volumes":[16]},{"term":"Pharmacokinetics","definition":"How the body absorbs, distributes, metabolises and eliminates a medicine.","volumes":[25]},{"term":"Pharmacovigilance","definition":"Detection and reporting of adverse effects and safety problems with medicines.","volumes":[25]},{"term":"Pharynx","definition":"The throat; a shared passage for air and food.","volumes":[21]},{"term":"Pheomelanin","definition":"A yellow-to-reddish sulfur-containing pigment that has lower UV photoprotection and can produce free radicals upon UV excitation.","volumes":[16]},{"term":"Phosphagen system (ATP-PC)","definition":"The fastest energy system, using stored ATP and phosphocreatine for maximal efforts of roughly up to 10 seconds.","volumes":[14]},{"term":"Photodamage (Photoaging)","definition":"Skin damage caused by cumulative solar UV exposure, leading to coarse wrinkles, solar elastosis, mottled pigmentation, and telangiectasias.","volumes":[16]},{"term":"Photophobia","definition":"Discomfort or intolerance associated with light.","volumes":[26]},{"term":"Photoreception","definition":"The detection of light by specialised cells.","volumes":[26]},{"term":"Photoreceptor","definition":"A retinal cell that converts light into an electrical signal.","volumes":[25]},{"term":"Phototransduction","definition":"The process by which photoreceptors convert light into electrical responses.","volumes":[26]},{"term":"Physical activity","definition":"Bodily movement producing energy expenditure, including daily tasks and exercise.","volumes":[13]},{"term":"Physical activity","definition":"Any bodily movement produced by skeletal muscles that requires energy expenditure (WHO definition). Includes exercise, work, transport and chores.","volumes":[14]},{"term":"Physical fitness","definition":"A set of attributes — endurance, strength, flexibility, balance, power, speed — that allow daily tasks and activity with energy to spare.","volumes":[14]},{"term":"Physiology","definition":"The study of how the body functions.","volumes":[21]},{"term":"Physiotherapy","definition":"Therapy for movement, strength, balance and physical function.","volumes":[25]},{"term":"Phytochemical","definition":"Any chemical compound produced by a plant. The word does not imply that a compound is beneficial or harmful.","volumes":[3]},{"term":"Pigment","definition":"A coloured substance; haemoglobin gives blood its red colour.","volumes":[21]},{"term":"Pigment epithelium","definition":"A cell layer that supports retinal photoreceptors and absorbs scattered light.","volumes":[26]},{"term":"Pinhole test","definition":"A simple clinical technique that can help distinguish some focusing-related blur.","volumes":[26]},{"term":"Piroctone Olamine","definition":"A modern, gentle antifungal and antioxidant compound frequently formulated in cosmetic anti-dandruff shampoos.","volumes":[16]},{"term":"Placebo","definition":"An inactive comparison intervention used to control expectation and other effects in trials.","volumes":[25]},{"term":"Placebo","definition":"An inactive or comparison intervention used in a study to help assess effects.","volumes":[26]},{"term":"Plasma","definition":"The liquid part of blood carrying cells and dissolved gases.","volumes":[21]},{"term":"Platelet","definition":"A cell fragment helping blood clot.","volumes":[21]},{"term":"Pleura","definition":"The double membrane around the lungs.","volumes":[21]},{"term":"Pleural effusion","definition":"Fluid between the pleural layers.","volumes":[21]},{"term":"Pleurisy","definition":"Inflammation of the pleura causing chest pain.","volumes":[21]},{"term":"Plexus","definition":"A network in which nerve fibres are redistributed before reaching their targets.","volumes":[25]},{"term":"Plyometrics","definition":"Jump training using the stretch-shortening cycle to develop power; introduce gradually and only when strength base is solid.","volumes":[14]},{"term":"Pneumoconiosis","definition":"Lung disease from inhaling certain dusts.","volumes":[21]},{"term":"Pneumonia","definition":"Infection inflaming the alveoli, often with fluid.","volumes":[21]},{"term":"Pneumothorax","definition":"Air in the pleural space causing lung collapse.","volumes":[21]},{"term":"PNF stretching","definition":"Proprioceptive neuromuscular facilitation — stretching combined with muscle contraction (e.g. contract-relax). Effective for range of motion, often used in rehabilitation.","volumes":[14]},{"term":"Pollen","definition":"A fine powder from plants that is a common allergen.","volumes":[21]},{"term":"Pollutant","definition":"A harmful substance in air, water or soil.","volumes":[21]},{"term":"Polyhydroxy Acid (PHA)","definition":"Second-generation chemical exfoliants like gluconolactone and lactobionic acid with larger molecular weights that gently exfoliate with minimal stinging.","volumes":[16]},{"term":"Polyp","definition":"A growth, such as nasal polyps, that can block airflow.","volumes":[21]},{"term":"Polysomnography","definition":"A detailed sleep study recording brain activity, breathing, oxygen and movement.","volumes":[25]},{"term":"Pons","definition":"A brainstem region helping regulate breathing.","volumes":[21]},{"term":"Pons","definition":"The middle brainstem region involved in relaying signals and several cranial nerve functions.","volumes":[25]},{"term":"Population","definition":"A group of people studied or served by public health.","volumes":[21]},{"term":"Positive feedback","definition":"A loop in which a response amplifies a change, usually over a limited time.","volumes":[25]},{"term":"Positive pressure","definition":"Air pushed in, as by CPAP or ventilators.","volumes":[21]},{"term":"Post-Inflammatory Hyperpigmentation (PIH)","definition":"Localized darkening of the skin occurring after cutaneous inflammation or injury (e.g., acne, cuts, aggressive chemical peels).","volumes":[16]},{"term":"Post-traumatic stress","definition":"Clinical symptoms following trauma. Requires professional assessment.","volumes":[13]},{"term":"Posterior segment","definition":"The back part of the eye, including the vitreous and retina.","volumes":[26]},{"term":"Power","definition":"Force produced quickly — strength × speed. Important for jumping, sprinting and reactive movements like catching a fall.","volumes":[14]},{"term":"PPDS","definition":"Prepacked for direct sale: food packed on the premises before the customer selects it. UK rules require a full ingredient list with allergens emphasised.","volumes":[9]},{"term":"Preformed vitamin A","definition":"Vitamin A in a form such as retinol, found in animal foods and some supplements.","volumes":[26]},{"term":"Prefrontal cortex","definition":"Frontal brain regions supporting planning, working memory and flexible control of behaviour.","volumes":[13]},{"term":"Prehabilitation","definition":"Preventive conditioning of commonly injured areas before demanding training or sport.","volumes":[14]},{"term":"Presbycusis","definition":"Hearing loss associated with ageing, often affecting high frequencies and speech understanding in noise.","volumes":[28]},{"term":"Prevalence","definition":"How common a condition is in a population.","volumes":[21]},{"term":"Prevalence","definition":"The proportion or number of people with a condition in a defined population at a time.","volumes":[26]},{"term":"Prevention","definition":"Measures to avoid disease or limit harm.","volumes":[21]},{"term":"Primary prevention","definition":"Action to reduce the chance of disease or injury before it occurs.","volumes":[25]},{"term":"Prism","definition":"An optical element that redirects light and may be prescribed for some alignment problems.","volumes":[26]},{"term":"Problem-focused coping","definition":"Coping that addresses the source of a stressor.","volumes":[13]},{"term":"Professional support","definition":"Care from qualified clinicians, counsellors, or other trained professionals.","volumes":[13]},{"term":"Prognosis","definition":"The likely course of a disease.","volumes":[21]},{"term":"Prognosis","definition":"The expected course and likely outcome of a condition for a particular person.","volumes":[25]},{"term":"Progressive lens","definition":"A lens with a gradual change in power for different viewing distances.","volumes":[26]},{"term":"Progressive muscle relaxation","definition":"Tensing then releasing muscle groups to increase awareness of tension.","volumes":[13]},{"term":"Progressive overload","definition":"Gradually increasing training demand (load, volume, intensity or difficulty) so the body keeps adapting.","volumes":[14]},{"term":"Progressive resistance exercise (PRE)","definition":"Systematically increasing resistance over time — the core method of strength training.","volumes":[14]},{"term":"Proliferative retinopathy","definition":"Retinal disease in which abnormal new blood vessels grow.","volumes":[26]},{"term":"Proprioception","definition":"The sense of body position and movement from sensors in muscles, tendons, joints and the inner ear. Trainable; key for balance.","volumes":[14]},{"term":"Proprioception","definition":"The sense of body position, movement and effort.","volumes":[25]},{"term":"Proprioception","definition":"The sense of body position and movement provided by receptors in muscles, joints and skin. It contributes to balance.","volumes":[28]},{"term":"Protective factor","definition":"A factor that reduces risk or supports wellbeing, such as social support or stable housing.","volumes":[13]},{"term":"Protective Styling","definition":"Hairstyling methods (twists, loose braids, buns) that tuck hair ends away and minimize daily combing, manipulation, and friction.","volumes":[16]},{"term":"Protein","definition":"A nutrient vital for muscle, including respiratory muscles.","volumes":[21]},{"term":"Provitamin A","definition":"A dietary substance, such as beta-carotene, that can be converted to vitamin A.","volumes":[26]},{"term":"Pruritus","definition":"The unpleasant cutaneous sensation that provokes an urge to scratch; transmitted via unmyelinated C-nerve fibers in the skin.","volumes":[16]},{"term":"Pseudofolliculitis Barbae","definition":"An inflammatory foreign-body reaction caused by curved hair shafts curling back and re-entering the skin after close shaving.","volumes":[16]},{"term":"Psoriasis","definition":"A chronic immune-mediated systemic disease causing accelerated keratinocyte turnover, leading to sharply demarcated silvery-scaled plaques.","volumes":[16]},{"term":"Psychological resilience","definition":"Adapting well after adversity through many interacting factors.","volumes":[13]},{"term":"Psychotherapy","definition":"Psychological treatment delivered by trained professionals.","volumes":[13]},{"term":"Public health","definition":"Efforts to protect and improve community health.","volumes":[21]},{"term":"Pulmonary","definition":"Relating to the lungs.","volumes":[21]},{"term":"Pulmonary embolism","definition":"A clot blocking a lung artery; a potential emergency.","volumes":[21]},{"term":"Pulmonary fibrosis","definition":"Scarring of lung tissue impairing gas exchange.","volumes":[21]},{"term":"Pulmonary hypertension","definition":"High pressure in lung arteries straining the right heart.","volumes":[21]},{"term":"Pulmonary rehabilitation","definition":"A supervised programme of exercise, education and support.","volumes":[21]},{"term":"Pulse oximeter","definition":"A device estimating oxygen saturation noninvasively.","volumes":[21]},{"term":"Pungency","definition":"A sensation of heat, bite or sting caused by compounds such as capsaicin (chilli), piperine (pepper) and allyl isothiocyanate (mustard, horseradish).","volumes":[3]},{"term":"Pupil reflex","definition":"A change in pupil size in response to a stimulus such as light.","volumes":[26]},{"term":"Pure-tone audiometry","definition":"A hearing test that measures the quietest tone a person can detect at selected frequencies and levels.","volumes":[28]},{"term":"Purging (Skincare)","definition":"A temporary surge of blemishes occurring when an active ingredient that accelerates cell turnover (like retinoids or AHAs) brings microcomedones to the surface.","volumes":[16]},{"term":"Purulent","definition":"Containing pus.","volumes":[21]},{"term":"Radon","definition":"A radioactive gas that can accumulate indoors and raise lung-cancer risk.","volumes":[21]},{"term":"Randomised controlled trial","definition":"A study that randomly assigns participants to interventions to compare outcomes fairly.","volumes":[25]},{"term":"Range of motion (ROM)","definition":"The extent of movement possible at a joint, in a given direction.","volumes":[14]},{"term":"Rating of perceived exertion","definition":"See RPE.","volumes":[14]},{"term":"Reactive airway","definition":"Airways that narrow readily to stimuli.","volumes":[21]},{"term":"Reading addition","definition":"Additional optical power used for near vision.","volumes":[26]},{"term":"Reappraisal","definition":"See Cognitive reappraisal.","volumes":[13]},{"term":"Receptive field","definition":"The region of space or body surface that influences a particular neuron.","volumes":[25]},{"term":"Receptor","definition":"A protein that binds a messenger and produces a cellular response.","volumes":[25]},{"term":"Recovery","definition":"Return of systems to baseline after demand, through rest, sleep and social support.","volumes":[13]},{"term":"Recovery","definition":"Return toward health after illness or exertion.","volumes":[21]},{"term":"Recovery heart rate","definition":"How quickly heart rate falls after exercise — a rough indicator of cardiovascular fitness; individual and context-dependent.","volumes":[14]},{"term":"RED-S (Relative Energy Deficiency in Sport)","definition":"A syndrome from sustained low energy availability relative to exercise load, affecting hormones, bones, immunity and performance. Needs professional care.","volumes":[14]},{"term":"Reference dose","definition":"A population-level estimate of the amount of an allergen that is unlikely to cause reactions in most allergic people; used in risk assessment, not for individuals.","volumes":[9]},{"term":"Reference range","definition":"The range of values usually found in a defined reference population for a test.","volumes":[25]},{"term":"Reflex","definition":"An automatic response, such as coughing or sneezing.","volumes":[21]},{"term":"Reflex arc","definition":"The basic neural circuit underlying a rapid stereotyped response to a stimulus.","volumes":[25]},{"term":"Refraction test","definition":"An assessment used to estimate optical correction for clearer focus.","volumes":[26]},{"term":"Refractive error","definition":"A focusing mismatch between the eye's optical power and its length.","volumes":[26]},{"term":"Refractory period","definition":"A brief interval after firing when another action potential is impossible or harder to trigger.","volumes":[25]},{"term":"Rehabilitation","definition":"Professionally guided movement and exercise to restore function after illness or injury.","volumes":[14]},{"term":"Rehabilitation","definition":"Restoring function and independence through structured care.","volumes":[21]},{"term":"Rehabilitation","definition":"Goal-directed care to improve function, independence and participation.","volumes":[25]},{"term":"Rehabilitation","definition":"Support and strategies that help people participate in activities important to them.","volumes":[26]},{"term":"Relapse","definition":"Return or worsening of a condition after improvement.","volumes":[25]},{"term":"Reliever","definition":"A quick-acting inhaler that opens airways during symptoms.","volumes":[21]},{"term":"REM sleep","definition":"A sleep stage with rapid eye movements, vivid dreams and muscle atonia.","volumes":[25]},{"term":"Remission","definition":"A period when signs or symptoms reduce or disappear, which may or may not mean cure.","volumes":[25]},{"term":"Remote microphone","definition":"A technology that sends a speaker’s voice directly to a listener’s hearing device or amplification system, improving the signal-to-noise ratio.","volumes":[28]},{"term":"Repetition (rep)","definition":"One complete movement of an exercise.","volumes":[14]},{"term":"Repetitive negative thinking","definition":"Repetitive thought focused on negative content, including worry and rumination.","volumes":[13]},{"term":"Repolarisation","definition":"Return of the membrane potential toward its negative resting value after depolarisation.","volumes":[25]},{"term":"Reservoir","definition":"A source where a pathogen survives, such as water or soil.","volumes":[21]},{"term":"Residual volume","definition":"Air remaining after maximal exhalation.","volumes":[21]},{"term":"Resilience","definition":"See Psychological resilience.","volumes":[13]},{"term":"Resistance training","definition":"Exercise in which muscles work against external resistance — bodyweight, bands, free weights, machines or everyday objects.","volumes":[14]},{"term":"Respiration","definition":"Broadly, the processes of gas exchange and energy production.","volumes":[21]},{"term":"Respiratory","definition":"Relating to breathing.","volumes":[21]},{"term":"Respiratory centre","definition":"Brainstem neurons setting breathing rhythm.","volumes":[21]},{"term":"Respiratory failure","definition":"Inadequate gas exchange causing low oxygen or high CO2.","volumes":[21]},{"term":"Respiratory membrane","definition":"The thin alveolar-capillary barrier for diffusion.","volumes":[21]},{"term":"Respiratory rate","definition":"Breaths per minute; a vital sign.","volumes":[21]},{"term":"Respite","definition":"Temporary relief for caregivers, through services or others.","volumes":[13]},{"term":"Rest","definition":"Periods of reduced demand that support recovery. A basic need, not a reward.","volumes":[13]},{"term":"Rest interval","definition":"The recovery time between sets or sessions — longer (2–3 min) for heavy strength work, shorter for endurance-type work.","volumes":[14]},{"term":"Resting membrane potential","definition":"The voltage across a resting neuron's membrane, normally negative inside.","volumes":[25]},{"term":"Restrictive","definition":"A pattern where lung inflation is limited.","volumes":[21]},{"term":"Reticular formation","definition":"A brainstem network involved in arousal, posture and autonomic control.","volumes":[25]},{"term":"Retinal imaging","definition":"Methods for recording images of the retina for clinical assessment.","volumes":[26]},{"term":"Retinal pigment epithelium","definition":"The pigmented cell layer supporting the photoreceptors at the back of the retina.","volumes":[26]},{"term":"Retinal tear","definition":"A break in the retina that may lead to retinal detachment.","volumes":[26]},{"term":"Retinol","definition":"An over-the-counter derivative of Vitamin A that converts inside skin cells into retinaldehyde and ultimately retinoic acid.","volumes":[16]},{"term":"Retinopathy","definition":"A general term for a disorder affecting the retina.","volumes":[26]},{"term":"Reuptake","definition":"Transport of neurotransmitter back into a presynaptic cell or supporting glia.","volumes":[25]},{"term":"Rhinitis","definition":"Inflammation of the nasal lining; allergic rhinitis is 'hay fever'.","volumes":[21]},{"term":"Rhizome","definition":"A horizontal underground stem that stores energy and produces roots and shoots, such as ginger and turmeric.","volumes":[3]},{"term":"Rib cage","definition":"The bones protecting the chest and supporting breathing.","volumes":[21]},{"term":"Risk factor","definition":"Something that increases the chance of disease.","volumes":[21]},{"term":"Risk reduction","definition":"Actions that lower the likelihood or severity of harm without guaranteeing prevention.","volumes":[25]},{"term":"Rod","definition":"A highly light-sensitive retinal photoreceptor supporting dim-light vision.","volumes":[25]},{"term":"Rods","definition":"Retinal photoreceptors particularly sensitive in dim light.","volumes":[26]},{"term":"Rosacea","definition":"A chronic inflammatory dermatosis causing central facial erythema, flushing, telangiectasias, and inflammatory papules or pustules.","volumes":[16]},{"term":"RPE (rating of perceived exertion)","definition":"A subjective scale of how hard exercise feels (e.g. 0–10). Correlates with heart rate and works without any device.","volumes":[14]},{"term":"Rumination","definition":"Repetitive, passive focus on distress and its causes, often without resolution.","volumes":[13]},{"term":"Salience","definition":"The quality of standing out as important, which the amygdala contributes to detecting.","volumes":[13]},{"term":"Saline","definition":"A salt solution; nasal saline rinses relieve congestion.","volumes":[21]},{"term":"Saline","definition":"A sterile salt-water solution used for specific medical purposes.","volumes":[26]},{"term":"Saltatory conduction","definition":"Fast propagation of action potentials between nodes of Ranvier in myelinated axons.","volumes":[25]},{"term":"Sarcomere","definition":"The basic contractile unit of muscle, containing actin and myosin filaments that slide past each other during contraction.","volumes":[14]},{"term":"Scleral lens","definition":"A large contact lens that rests on the sclera and vaults over the cornea.","volumes":[26]},{"term":"Screen magnifier","definition":"Software that enlarges content displayed on a screen.","volumes":[26]},{"term":"Screening","definition":"A preliminary process identifying people who may need further evaluation.","volumes":[26]},{"term":"Sebaceous Gland","definition":"A microscopic exocrine gland in the dermis, usually associated with hair follicles, that secretes an oily lubricating mixture called sebum.","volumes":[16]},{"term":"Seborrhoeic Dermatitis","definition":"A chronic inflammatory skin condition characterized by erythema, greasy yellowish scales, and pruritus in areas rich in sebaceous glands.","volumes":[16]},{"term":"Sebum","definition":"A complex mixture of squalene, triglycerides, wax esters, and free fatty acids produced by sebaceous glands.","volumes":[16]},{"term":"Secondary metabolite","definition":"A compound not essential for basic plant growth but involved in defence, attraction or protection. Many flavours are secondary metabolites.","volumes":[3]},{"term":"Secondary prevention","definition":"Early detection or action to limit harm once a risk factor or condition is present.","volumes":[25]},{"term":"Secretory IgA","definition":"An antibody protecting mucosal surfaces.","volumes":[21]},{"term":"Sedative","definition":"A medicine causing drowsiness; can affect breathing if misused.","volumes":[21]},{"term":"Sedentary behaviour","definition":"Waking time spent sitting, reclining or lying with low energy expenditure. A risk factor distinct from physical inactivity.","volumes":[14]},{"term":"Seizure","definition":"A transient event of abnormal excessive or synchronous neuronal activity.","volumes":[25]},{"term":"Self-compassion","definition":"Kindness toward oneself during difficulty, recognising shared humanity and mindful awareness.","volumes":[13]},{"term":"Self-criticism","definition":"Harsh judgement of oneself, often linked with rumination.","volumes":[13]},{"term":"Self-esteem","definition":"An overall evaluation of one's own worth.","volumes":[13]},{"term":"Semicircular canal","definition":"A fluid-filled vestibular structure that detects rotational head acceleration.","volumes":[25]},{"term":"Sensation","definition":"The perception of stimuli such as breathlessness.","volumes":[21]},{"term":"Sensitisation","definition":"The presence of allergen-specific IgE without necessarily having clinical allergy.","volumes":[9]},{"term":"Sensitive period","definition":"A developmental window when a particular experience has especially strong effects.","volumes":[25]},{"term":"Sensorineural hearing loss","definition":"Hearing loss caused by dysfunction of the inner ear, particularly cochlear hair cells, or the auditory nerve. It is often permanent.","volumes":[28]},{"term":"Sensory adaptation","definition":"A decrease in response during sustained or repeated stimulation.","volumes":[25]},{"term":"Septum","definition":"A wall dividing structures, such as the nasal septum.","volumes":[21]},{"term":"Sequelae","definition":"Conditions following a disease, such as post-viral symptoms.","volumes":[21]},{"term":"Serotonin","definition":"A neurotransmitter and signalling molecule with widespread effects on mood, sleep and gut function.","volumes":[25]},{"term":"Serum","definition":"The fluid part of blood after clotting.","volumes":[21]},{"term":"Serum Ferritin","definition":"The primary iron-storage protein measured in blood to assess systemic iron stores.","volumes":[16]},{"term":"Sesame","definition":"A seed used whole, as oil or paste (tahini). A declared allergen in many jurisdictions.","volumes":[9]},{"term":"Set","definition":"A group of consecutive repetitions.","volumes":[14]},{"term":"Shadowing","definition":"An area seen on imaging suggesting abnormality.","volumes":[21]},{"term":"Shame","definition":"A painful feeling focused on the self as flawed. Often less helpful than guilt.","volumes":[13]},{"term":"Shortness of breath","definition":"A common term for dyspnoea.","volumes":[21]},{"term":"Sign language","definition":"A complete visual language with its own grammar, vocabulary and communities. Sign languages differ around the world and are not universal.","volumes":[28]},{"term":"Silica","definition":"A mineral dust that can cause silicosis.","volumes":[21]},{"term":"Silicones (Haircare)","definition":"Synthetic polymers (like amodimethicone or cyclomethicone) that coat the hair shaft, smooth the cuticle, reduce comb friction, and add shine.","volumes":[16]},{"term":"Silicosis","definition":"Lung disease from inhaled silica dust.","volumes":[21]},{"term":"Sinuses","definition":"Air-filled spaces in the skull connected to the nose.","volumes":[21]},{"term":"Size principle","definition":"Motor units are recruited from small to large as force demand increases.","volumes":[14]},{"term":"Skeletal muscle","definition":"Voluntary, striated muscle attached to bones via tendons; the tissue trained in resistance exercise.","volumes":[14]},{"term":"Skin Microbiome","definition":"The diverse ecosystem of trillions of commensal bacteria, fungi, viruses, and mites inhabiting the skin surface.","volumes":[16]},{"term":"Skin Tear","definition":"A traumatic separation of the epidermis from the dermis, frequently seen in frail, atrophic skin of older adults due to minor friction or shearing forces.","volumes":[16]},{"term":"Sleep apnoea","definition":"Repeated breathing pauses during sleep.","volumes":[21]},{"term":"Sleep apnoea","definition":"A disorder of repeated breathing pauses during sleep that requires assessment.","volumes":[25]},{"term":"Sleep homeostasis","definition":"Increasing sleep pressure during wakefulness that is relieved by sleep.","volumes":[25]},{"term":"Sleep hygiene","definition":"Habits supporting sleep, such as regular wake times and reduced evening light.","volumes":[13]},{"term":"Sleep hygiene","definition":"Practical habits that support sleep timing, duration and environment.","volumes":[25]},{"term":"Sliding filament theory","definition":"The mechanism of contraction: myosin heads pull actin filaments within sarcomeres, shortening the muscle.","volumes":[14]},{"term":"Slit beam","definition":"A narrow beam of light used during a slit-lamp examination.","volumes":[26]},{"term":"Slow-twitch (type I) fibres","definition":"Muscle fibres that are fatigue-resistant and suited to endurance activity.","volumes":[14]},{"term":"Slow-wave sleep","definition":"Deep non-REM sleep with prominent slow brain oscillations.","volumes":[25]},{"term":"Slugging","definition":"A skincare practice of applying an occlusive petrolatum ointment over moisturized skin overnight to create an impermeable moisture seal.","volumes":[16]},{"term":"Smooth muscle","definition":"Involuntary muscle controlling airway diameter.","volumes":[21]},{"term":"Sneeze","definition":"A forced expulsion clearing the nasal passages.","volumes":[21]},{"term":"Snellen chart","definition":"A type of distance visual acuity chart using standardised symbols.","volumes":[26]},{"term":"Social support","definition":"Help, connection and encouragement from others, including emotional, practical and informational forms.","volumes":[13]},{"term":"Sodium Lauryl Sulfate (SLS)","definition":"A strong anionic detergent surfactant frequently used as an experimental positive control in dermatological skin-irritation research.","volumes":[16]},{"term":"Soma","definition":"The cell body of a neuron containing its nucleus and metabolic machinery.","volumes":[25]},{"term":"Somatic nervous system","definition":"The division controlling skeletal muscles and receiving conscious somatic sensation.","volumes":[25]},{"term":"Somatosensory cortex","definition":"The cortical strip receiving touch, temperature, pain and body-position input.","volumes":[25]},{"term":"Spasticity","definition":"Increased muscle tone due to disturbed motor control after upper motor neuron injury.","volumes":[25]},{"term":"Species","definition":"The second word of a botanical name, identifying a particular kind of plant, for example verum in Cinnamomum verum.","volumes":[3]},{"term":"Specificity","definition":"The principle that adaptations match the specific demands imposed — train the qualities you want.","volumes":[14]},{"term":"Speech-language therapy","definition":"Support for communication and swallowing difficulties.","volumes":[25]},{"term":"SPF (Sun Protection Factor)","definition":"A laboratory measure of how much solar UV energy (primarily UVB) is required to produce erythema on protected skin compared to unprotected skin.","volumes":[16]},{"term":"Sphere","definition":"The component of an optical prescription describing overall lens power.","volumes":[26]},{"term":"Spice","definition":"In cooking, usually dried seeds, fruits, bark, roots, buds or other non-leafy parts used for flavour, colour or aroma.","volumes":[3]},{"term":"Spinal cord","definition":"The part of the central nervous system that connects the brain with the body and contains reflex circuits.","volumes":[25]},{"term":"Spinal cord injury","definition":"Damage to the spinal cord that can affect movement, sensation and autonomic functions.","volumes":[25]},{"term":"Sport","definition":"Rule-governed, often competitive physical activity involving skill and, typically, structured training.","volumes":[14]},{"term":"Sprain","definition":"Stretching or tearing of a ligament, usually around a joint, often with swelling and bruising — e.g. an ankle sprain.","volumes":[14]},{"term":"Sputum","definition":"Mucus coughed up from the airways.","volumes":[21]},{"term":"Squalane","definition":"A hydrogenated, stable form of squalene (a natural component of human sebum) derived from olives or sugarcane.","volumes":[16]},{"term":"Squamous Cell Carcinoma (SCC)","definition":"A malignant proliferation of cutaneous epidermal keratinocytes, often arising in sun-damaged skin or actinic keratosis precursor lesions.","volumes":[16]},{"term":"Static balance","definition":"Holding a stationary position, e.g. standing on one leg.","volumes":[14]},{"term":"Static stretching","definition":"Holding a muscle in a lengthened position for a set time (typically 15–60 s). Best after activity or for relaxation.","volumes":[14]},{"term":"Status epilepticus","definition":"A prolonged seizure or repeated seizures without recovery, requiring emergency treatment.","volumes":[25]},{"term":"Stereocilia","definition":"Microscopic hair-like projections on sensory hair cells in the inner ear. Their movement initiates the conversion of mechanical vibration into electrical signals.","volumes":[28]},{"term":"Stereopsis","definition":"A depth cue produced by comparing slightly different images from the two eyes.","volumes":[26]},{"term":"Steroid","definition":"A class of medicines with important uses and potential risks when incorrectly used.","volumes":[26]},{"term":"Stethoscope","definition":"A device listening to breath and heart sounds.","volumes":[21]},{"term":"Stigma","definition":"Negative judgement that can delay care; avoid in health messaging.","volumes":[21]},{"term":"Strain","definition":"Tearing or overstretching of muscle fibres or a tendon, often felt as sudden sharp pain during a loaded movement.","volumes":[14]},{"term":"Stratum Corneum","definition":"The uppermost layer of the epidermis, consisting of dead, flattened, keratin-filled corneocytes embedded in a lipid-rich extracellular matrix.","volumes":[16]},{"term":"Strength","definition":"The capacity of the neuromuscular system to produce force against resistance.","volumes":[14]},{"term":"Stress response","definition":"The coordinated physiological and psychological reaction to a stressor.","volumes":[13]},{"term":"Stressor","definition":"An event or condition placing demands on a person.","volumes":[13]},{"term":"Stretch reflex","definition":"A protective muscle contraction triggered when a muscle is stretched rapidly — a reason ballistic bouncing is discouraged.","volumes":[14]},{"term":"Stretch-shortening cycle","definition":"A rapid stretch (eccentric) followed immediately by shortening (concentric), storing and releasing elastic energy — the basis of jumping and running efficiency.","volumes":[14]},{"term":"Stridor","definition":"A high-pitched noise on inhalation suggesting upper-airway narrowing.","volumes":[21]},{"term":"Stroke","definition":"Sudden brain dysfunction caused by blocked or ruptured blood vessels and requiring emergency care.","volumes":[25]},{"term":"Stroke volume (SV)","definition":"The volume of blood ejected by the heart per beat. Increases with aerobic training.","volumes":[14]},{"term":"Submucosa","definition":"The layer beneath the airway lining.","volumes":[21]},{"term":"Submucosal plexus","definition":"An enteric network that influences gut secretion and blood flow.","volumes":[25]},{"term":"Subspecies / variety","definition":"Ranks below species used for distinct populations within it (subsp., var.).","volumes":[3]},{"term":"Substance P","definition":"A neuropeptide released by cutaneous sensory nerve endings during emotional stress that triggers mast cell degranulation and inflammation.","volumes":[16]},{"term":"Substance use","definition":"Use of alcohol, drugs or other substances; problematic use may need support.","volumes":[13]},{"term":"Subungual Hematoma","definition":"A collection of blood beneath the nail plate usually resulting from acute blunt trauma (e.g., slamming a finger in a door).","volumes":[16]},{"term":"Sudden sensorineural hearing loss","definition":"A rapid loss of hearing, usually in one ear, that needs urgent assessment. It is not a condition to watch at home for weeks.","volumes":[28]},{"term":"Sulphites","definition":"Preservatives (sulphur dioxide and sulphites) that can cause reactions in sensitive people. Declared at ≥10 mg/kg or 10 mg/L in many jurisdictions.","volumes":[9]},{"term":"Sulphur dioxide (SO2)","definition":"A gas from burning fossil fuels that irritates airways.","volumes":[21]},{"term":"Supercompensation","definition":"The rebound to a higher performance level after recovery from a training stimulus — the basis of progressive adaptation.","volumes":[14]},{"term":"Suppression","definition":"Holding back the outward expression of emotion. Has some costs when used habitually.","volumes":[13]},{"term":"Surfactant","definition":"A surface-active agent possessing both hydrophobic and hydrophilic molecular regions that emulsifies oils and allows them to be rinsed with water.","volumes":[16]},{"term":"Surfactant","definition":"A substance keeping alveoli open by lowering surface tension.","volumes":[21]},{"term":"Sympathetic chain","definition":"Paired paravertebral ganglia that distribute sympathetic nerve fibres.","volumes":[25]},{"term":"Sympathetic nervous system","definition":"The autonomic branch associated with mobilisation and alertness.","volumes":[13]},{"term":"Symptom","definition":"A felt sign of illness, such as cough or breathlessness.","volumes":[21]},{"term":"Synapse","definition":"The specialised junction where a neuron communicates with another cell.","volumes":[25]},{"term":"Synaptic pruning","definition":"Experience-dependent removal of some synapses to refine neural circuits.","volumes":[25]},{"term":"Synaptic transmission","definition":"Communication between neurons or target cells across a synapse.","volumes":[25]},{"term":"Syncope","definition":"Fainting or loss of consciousness.","volumes":[21]},{"term":"Synergist","definition":"A muscle that assists the agonist in producing a movement.","volumes":[14]},{"term":"Synonym","definition":"A scientific name no longer accepted that refers to the same plant as the accepted name.","volumes":[3]},{"term":"Synovial fluid","definition":"Lubricating fluid inside synovial joints that nourishes cartilage and reduces friction.","volumes":[14]},{"term":"Systematic review","definition":"A structured and transparent search and appraisal of all relevant studies on a question.","volumes":[3]},{"term":"Systematic review","definition":"A structured summary of research studies addressing a defined question.","volumes":[25]},{"term":"Systematic review","definition":"A structured synthesis of research addressing a defined question.","volumes":[26]},{"term":"Systemic","definition":"Affecting the whole body, not just one part.","volumes":[21]},{"term":"Tachypnoea","definition":"Abnormally fast breathing.","volumes":[21]},{"term":"Tactile marking","definition":"A raised or textured cue that can be identified by touch.","volumes":[26]},{"term":"Talk test","definition":"A simple intensity check: moderate = talk but not sing; vigorous = only short phrases.","volumes":[14]},{"term":"Taper","definition":"A planned gradual dose reduction to prevent withdrawal or worsening of a condition.","volumes":[25]},{"term":"Taste bud","definition":"A cluster of receptor cells detecting basic taste qualities.","volumes":[25]},{"term":"Tau","definition":"A structural protein that can form abnormal tangles in several neurodegenerative conditions.","volumes":[25]},{"term":"Tear break-up time","definition":"A clinical measure used in assessing tear-film stability.","volumes":[26]},{"term":"Tear drainage","definition":"The flow of tears from the eye surface through the tear drainage system.","volumes":[26]},{"term":"Tear gland","definition":"A gland contributing fluid to the tear film, including the lacrimal gland.","volumes":[26]},{"term":"Telogen Effluvium","definition":"A form of non-scarring, diffuse hair shedding precipitated 2 to 4 months following a systemic physiological or psychological stressor.","volumes":[16]},{"term":"Telogen Phase","definition":"The resting phase of the hair cycle lasting approximately 2 to 4 months before the club hair is shed.","volumes":[16]},{"term":"Tempering (tadka, chaunk)","definition":"Heating whole spices in hot fat until they release aroma, then adding them to or over a dish.","volumes":[3]},{"term":"Temporal lobe","definition":"The lateral cerebral lobe involved in hearing, language comprehension, memory and emotion.","volumes":[25]},{"term":"Tendinopathy","definition":"A painful, degenerative-overload condition of a tendon from repeated excessive load — e.g. Achilles or patellar tendinopathy.","volumes":[14]},{"term":"Tendon","definition":"Fibrous connective tissue connecting muscle to bone, transmitting force. Adapts to gradual loading more slowly than muscle.","volumes":[14]},{"term":"Tendonitis","definition":"Older term for acute tendon inflammation; most chronic tendon pain is tendinopathy (degenerative overload).","volumes":[14]},{"term":"Terpene","definition":"A large class of aromatic plant compounds, many of which contribute citrus, pine, floral or minty aromas.","volumes":[3]},{"term":"Thalamus","definition":"A relay and integration centre for most sensory and many motor pathways.","volumes":[25]},{"term":"Thermoregulation","definition":"Coordinated control of heat production and loss to regulate body temperature.","volumes":[25]},{"term":"Thiamine","definition":"Vitamin B1, essential for carbohydrate metabolism and nerve function.","volumes":[25]},{"term":"Thoracic","definition":"Relating to the chest.","volumes":[21]},{"term":"Thorax","definition":"The chest cavity housing the lungs and heart.","volumes":[21]},{"term":"Thought record","definition":"A written tool noting a situation, thought, feeling and alternative view.","volumes":[13]},{"term":"Threat detection","definition":"Brain and body processes that identify potential danger.","volumes":[13]},{"term":"Threshold","definition":"A level at which an effect begins, such as an exposure limit.","volumes":[21]},{"term":"Threshold","definition":"The membrane voltage at which an action potential is usually initiated.","volumes":[25]},{"term":"Throat","definition":"The pharynx; a shared airway and food passage.","volumes":[21]},{"term":"Tidal volume","definition":"Air moved in and out during normal breathing.","volumes":[21]},{"term":"Tincture","definition":"A concentrated liquid extract made with alcohol, used mainly in herbal products rather than cooking.","volumes":[3]},{"term":"Tinea Capitis","definition":"A fungal dermatophyte infection of the scalp and hair shafts, causing patchy scaly hair loss with broken hairs, common in schoolchildren.","volumes":[16]},{"term":"Tinnitus","definition":"The perception of sound without an external source, such as ringing, buzzing, hissing or humming. It is a symptom with many possible contributors.","volumes":[28]},{"term":"Tissue","definition":"A group of cells working together, such as lung tissue.","volumes":[21]},{"term":"Titanium Dioxide","definition":"An inorganic mineral UV filter effective across UVB and short UVA wavelengths, often combined with zinc oxide.","volumes":[16]},{"term":"Tobacco","definition":"Leaves smoked or chewed; a major cause of lung disease.","volumes":[21]},{"term":"Toxicity","definition":"Harm caused by excessive exposure to a substance, including some nutrients.","volumes":[25]},{"term":"Trabecular meshwork","definition":"Tissue at the drainage angle through which much aqueous humour leaves the eye.","volumes":[26]},{"term":"Trachea","definition":"The windpipe carrying air from larynx to bronchi.","volumes":[21]},{"term":"Traction Alopecia","definition":"Hair loss caused by persistent, sustained pulling tension on hair follicles from tight hairstyles like tight braids, ponytails, or extensions.","volumes":[16]},{"term":"Training frequency","definition":"How many training sessions per week.","volumes":[14]},{"term":"Training load","definition":"The total training stress imposed — volume × intensity × frequency — which must be balanced by recovery.","volumes":[14]},{"term":"Training volume","definition":"The total amount of work in a session or week — sets × reps × load. A key driver of adaptation, progressed gradually.","volumes":[14]},{"term":"Transactional model","definition":"Lazarus and Folkman's model of stress as a relationship between person and environment through appraisal.","volumes":[13]},{"term":"Transduction","definition":"Conversion of one form of energy, such as light or pressure, into a neural signal.","volumes":[25]},{"term":"Transepidermal Water Loss (TEWL)","definition":"The physiological quantity of water vapor that diffuses passively from inside the body through the stratum corneum to the environment.","volumes":[16]},{"term":"Transient ischaemic attack","definition":"A temporary stroke-like episode that resolves but is a major warning sign.","volumes":[25]},{"term":"Transverse abdominis","definition":"The deep, corset-like abdominal muscle that stabilises the trunk and manages intra-abdominal pressure.","volumes":[14]},{"term":"Trauma","definition":"Experience overwhelming a person's capacity to cope. Responses vary widely.","volumes":[13]},{"term":"Trauma-informed care","definition":"An approach emphasising safety, trust, choice, collaboration and cultural respect.","volumes":[13]},{"term":"Tree nuts","definition":"Nuts that grow on trees, such as almond, hazelnut, walnut, cashew, pecan, pistachio, Brazil nut and macadamia. Lists vary by country.","volumes":[9]},{"term":"Tretinoin (Retinoic Acid)","definition":"A prescription-only direct-binding retinoid that acts immediately on cellular retinoic acid receptors (RAR) to normalize follicular keratinization.","volumes":[16]},{"term":"Triage","definition":"The process of prioritising urgency of care based on risk.","volumes":[25]},{"term":"Trichoptilosis","definition":"The technical term for split ends, representing longitudinal splitting of the distal hair shaft due to wear and cuticle erosion.","volumes":[16]},{"term":"Trigeminal neuralgia","definition":"Severe, often electric facial pain in the trigeminal nerve distribution.","volumes":[25]},{"term":"Triggers","definition":"Cues that bring up strong emotional responses, often linked to past experiences.","volumes":[13]},{"term":"Tropomyosin","definition":"A muscle protein in crustaceans, molluscs and some other animals that is a major shellfish allergen and can drive cross-reactivity.","volumes":[9]},{"term":"Tuberculosis (TB)","definition":"A treatable bacterial infection, usually of the lungs.","volumes":[21]},{"term":"Turbinates","definition":"Scroll-shaped bones warming and filtering nasal air.","volumes":[21]},{"term":"Tympanic membrane","definition":"The medical name for the eardrum.","volumes":[28]},{"term":"Tympanometry","definition":"A test of middle-ear movement and pressure using a small probe in the ear canal. It provides indirect information about the middle ear and eardrum.","volumes":[28]},{"term":"Type I / Type II fibres","definition":"See slow-twitch and fast-twitch fibres.","volumes":[14]},{"term":"Ugly Duckling Sign","definition":"A dermatological observation principle that a pigmented lesion that looks visibly distinct or different from all other moles is suspicious.","volumes":[16]},{"term":"Ultraviolet A","definition":"A range of ultraviolet radiation with longer wavelengths than UVB.","volumes":[26]},{"term":"Ultraviolet B","definition":"A range of ultraviolet radiation with shorter wavelengths than UVA.","volumes":[26]},{"term":"Umami","definition":"The savoury taste associated with glutamate and some other compounds.","volumes":[3]},{"term":"Umami","definition":"A basic savoury taste quality associated with glutamate and nucleotides.","volumes":[25]},{"term":"Upper motor neuron","definition":"A neuron in the brain or brainstem that influences lower motor neurons.","volumes":[25]},{"term":"Upper respiratory tract","definition":"Structures above the vocal cords: nose, sinuses, pharynx, larynx.","volumes":[21]},{"term":"Urticaria (Hives)","definition":"Transient, intensely itchy erythematous wheals and edematous plaques caused by localized mast cell degranulation and histamine release.","volumes":[16]},{"term":"Uvea","definition":"The vascular middle layer of the eye, including the iris, ciliary body and choroid.","volumes":[26]},{"term":"Vaccination","definition":"The act of receiving a vaccine.","volumes":[21]},{"term":"Vaccine","definition":"A product training the immune system against a pathogen.","volumes":[21]},{"term":"Vagus nerve","definition":"A major nerve linking brain and many organs, involved in autonomic and gut communication.","volumes":[13]},{"term":"Vagus nerve","definition":"A major cranial nerve carrying extensive parasympathetic and sensory fibres.","volumes":[25]},{"term":"Valsalva manoeuvre","definition":"Holding your breath and bearing down during a heavy lift; raises blood pressure sharply — breathe continuously instead.","volumes":[14]},{"term":"Vegan","definition":"A dietary pattern excluding all animal-derived foods. It does not imply absence of nuts, soy, wheat, sesame or other allergens.","volumes":[9]},{"term":"Ventilation","definition":"The mechanical movement of air into and out of the lungs.","volumes":[21]},{"term":"Ventilation-perfusion (V/Q)","definition":"The matching of airflow and blood flow in the lungs.","volumes":[21]},{"term":"Ventilator","definition":"A machine supporting or replacing breathing.","volumes":[21]},{"term":"Ventral horn","definition":"The region of spinal grey matter containing many motor neuron cell bodies.","volumes":[25]},{"term":"Ventricle","definition":"A fluid-filled space within the brain that contains cerebrospinal fluid.","volumes":[25]},{"term":"Vergence","definition":"Coordinated movement of the eyes in opposite directions to maintain fixation.","volumes":[26]},{"term":"Vertigo","definition":"A false sensation that you or the environment is spinning or moving. It is a symptom, not a diagnosis.","volumes":[28]},{"term":"Vestibular","definition":"See vestibular system.","volumes":[14]},{"term":"Vestibular migraine","definition":"A condition with recurrent vestibular symptoms associated with migraine features. It may occur without headache and is diagnosed using clinical criteria.","volumes":[28]},{"term":"Vestibular neuritis","definition":"A clinical syndrome of sudden, prolonged vertigo often attributed to inflammation of the vestibular nerve, usually without hearing loss.","volumes":[28]},{"term":"Vestibular rehabilitation","definition":"A structured, individually tailored exercise programme for vestibular and balance symptoms, usually delivered by a trained clinician.","volumes":[28]},{"term":"Vestibular schwannoma","definition":"A usually slow-growing, non-cancerous tumour of the vestibular nerve. It can cause one-sided hearing loss, tinnitus or imbalance.","volumes":[28]},{"term":"Vestibular system","definition":"The inner-ear balance system that senses head position and motion; one of three inputs to balance.","volumes":[14]},{"term":"Vestibular system","definition":"The inner-ear balance organs—semicircular canals, utricle and saccule—and their central pathways.","volumes":[28]},{"term":"Vestibulo-ocular reflex (VOR)","definition":"A fast reflex that moves the eyes to stabilise vision when the head rotates.","volumes":[28]},{"term":"Virus","definition":"A microscopic agent causing many respiratory infections.","volumes":[21]},{"term":"Visible","definition":"Able to be seen; important for legible diagrams.","volumes":[21]},{"term":"Vision loss","definition":"A reduction in visual function that may have many causes and effects.","volumes":[26]},{"term":"Vision rehabilitation service","definition":"A service providing personalised strategies and tools for visual tasks.","volumes":[26]},{"term":"Visual acuity chart","definition":"A standardised chart used to assess the ability to identify details or symbols.","volumes":[26]},{"term":"Visual cortex processing","definition":"The interpretation of neural visual signals in the brain's visual cortical areas.","volumes":[26]},{"term":"Visual field test","definition":"An assessment of sensitivity across a person's visual field.","volumes":[26]},{"term":"Visual impairment","definition":"A limitation in visual function that can interact with environmental barriers.","volumes":[26]},{"term":"Visual pathway lesion","definition":"Damage at a point in the neural route carrying visual information.","volumes":[26]},{"term":"Visual pigment","definition":"A light-sensitive molecule in a photoreceptor involved in detecting light.","volumes":[26]},{"term":"Visual rehabilitation goal","definition":"An activity or outcome a person chooses to work towards with support.","volumes":[26]},{"term":"Vital capacity","definition":"The maximum air moved voluntarily.","volumes":[21]},{"term":"Vitamin B12","definition":"A vitamin needed for blood formation and neurological function, obtained mainly from animal foods or fortification.","volumes":[25]},{"term":"Vitamin B6","definition":"A vitamin involved in many enzyme reactions, including neurotransmitter synthesis; excess can cause neuropathy.","volumes":[25]},{"term":"Vitamin D","definition":"A nutrient and hormone precursor important for bone, muscle and immune function.","volumes":[25]},{"term":"Vitamin D Receptor (VDR)","definition":"Nuclear receptors expressed in epidermal keratinocytes and hair follicle dermal papilla cells that regulate hair cycle initiation.","volumes":[16]},{"term":"Vitiligo","definition":"A chronic autoimmune disorder in which cytotoxic T-lymphocytes target and destroy melanocytes, resulting in macules of complete depigmentation.","volumes":[16]},{"term":"Vitreous detachment","definition":"Separation of the vitreous from the retina, which can sometimes cause a retinal tear.","volumes":[26]},{"term":"Vitreous humour","definition":"The transparent gel-like material filling much of the eye behind the lens.","volumes":[26]},{"term":"VO2max","definition":"See aerobic capacity.","volumes":[14]},{"term":"Vocal cords","definition":"Folds in the larynx that produce voice.","volumes":[21]},{"term":"Volatile compound","definition":"A molecule that evaporates easily at room temperature and can reach the nose as aroma.","volumes":[3]},{"term":"Volatile organic compound (VOC)","definition":"Gases from products that can irritate airways.","volumes":[21]},{"term":"Vulnerability","definition":"Increased susceptibility to harm due to circumstances. Structural factors often contribute.","volumes":[13]},{"term":"Warm-up","definition":"Gradual preparation raising body temperature, blood flow and neuromuscular readiness — typically 5–15 minutes before a session.","volumes":[14]},{"term":"Warm-up (specific)","definition":"Light rehearsal of the session's movements and muscles after the general warm-up.","volumes":[14]},{"term":"Wavelength-sensitive cones","definition":"Cone photoreceptors that respond differently across visible wavelengths.","volumes":[26]},{"term":"Weight-bearing exercise","definition":"Activity where the body supports its own weight against gravity — important for bone health.","volumes":[14]},{"term":"Wellbeing","definition":"A broad state including emotional, physical, social and psychological functioning.","volumes":[13]},{"term":"Wet AMD","definition":"An advanced form of AMD involving abnormal blood vessel growth beneath or in the retina.","volumes":[26]},{"term":"Wheeze","definition":"A high-pitched sound from narrowed airways.","volumes":[21]},{"term":"Whey","definition":"The liquid portion of milk that remains after curds form; contains whey proteins that can cause milk allergy.","volumes":[9]},{"term":"White matter","definition":"Nervous tissue rich in myelinated axons that form communication tracts.","volumes":[25]},{"term":"White pupil reflex","definition":"A pale reflection from the pupil that can indicate a condition requiring prompt assessment.","volumes":[26]},{"term":"Whole spice","definition":"A spice sold in its intact form: seeds, pods, bark pieces, buds and similar.","volumes":[3]},{"term":"Wild-harvested","definition":"Collected from natural populations rather than cultivated. Raises conservation and identification issues.","volumes":[3]},{"term":"Withdrawal","definition":"Symptoms when stopping a substance, such as nicotine.","volumes":[21]},{"term":"Work-to-rest ratio","definition":"The proportion of work to recovery in interval training — e.g. 1:2 (work 30 s, rest 60 s).","volumes":[14]},{"term":"Working memory","definition":"Short-term capacity to hold and manipulate information.","volumes":[13]},{"term":"Working memory","definition":"Temporary holding and manipulation of information for a current task.","volumes":[25]},{"term":"Workout","definition":"A single session of planned exercise.","volumes":[14]},{"term":"Worry","definition":"Repetitive thinking about possible future problems.","volumes":[13]},{"term":"Worry loop","definition":"A cycle in which concern leads to imagined outcomes and returns to concern without resolution.","volumes":[13]},{"term":"X-ray","definition":"Imaging using radiation to view the chest.","volumes":[21]},{"term":"Xerosis Cutis","definition":"The medical term for abnormally dry skin resulting from deficient moisture and intercellular lipids in the stratum corneum.","volumes":[16]},{"term":"Yawn","definition":"A deep involuntary breath, possibly aiding lung recruitment.","volumes":[21]},{"term":"Yearly","definition":"Annually; relevant to check-ups and vaccines.","volumes":[21]},{"term":"Zeaxanthin","definition":"A dietary carotenoid that contributes to pigment in the macula.","volumes":[26]},{"term":"Zinc (Dermatology)","definition":"An essential trace element functioning as a cofactor for over 300 enzymes, critical for cell division, DNA repair, and wound healing.","volumes":[16]},{"term":"Zinc Oxide","definition":"An inorganic (mineral) sunscreen filter that reflects, scatters, and absorbs both UVA and UVB rays, known for high photo-stability and minimal irritation.","volumes":[16]},{"term":"Zinc Pyrithione","definition":"A coordination complex of zinc with antimicrobial and antifungal properties long used in over-the-counter anti-dandruff cleansers.","volumes":[16]},{"term":"Zone","definition":"An area, such as a pollution or ventilation zone.","volumes":[21]},{"term":"Zonules","definition":"Fine fibres that connect the lens to the ciliary body.","volumes":[26]}];
